window.ACADEMY={"sources": {"S1": ["Guide d'application de la réglementation, fascicule 1 (v2, nov. 2019)", "https://www.reseaux-et-canalisations.ineris.fr/gu-presentation/userfile?path=/fichiers/Guides_techniques/Fascicule1_en_vigueur_01012020.pdf", "Lu partiellement : texte obtenu tronqué au §5.4.1."], "S2": ["Guide technique des travaux, fascicule 2 v3, consolidé au 18 février 2024", "https://www.observatoire-national-dt-dict.fr/wp-content/uploads/2024/05/2024_Fascicule-2-GUIDE-TECHNIQUE_V3.pdf", "Lu jusqu'à la page 43 (§3.8.5). Chapitres 4 à 9, dont le chapitre 5 (techniques) et le chapitre 8 (conduite à tenir par réseau), non lus."], "S3": ["Guide pratique « Travaux à proximité des réseaux », FFB, FNTP, OPPBTP, SGAMbtp, nov. 2022", "https://www.smabtp.fr/sma/upload/docs/application/pdf/2023-01/guide_travaux_a_proximite_des_reseaux__200123.pdf", "Lu jusqu'à la p. 46 ; annexes non lues."], "S4": ["INRS ED 6164, Travaux à proximité des réseaux (avril 2014)", "https://www.inrs.fr/dam/inrs/CataloguePapier/ED/TI-ED-6164.pdf", "Édition antérieure à la réforme ; lu jusqu'à la section 2.4.5. Citée pour le contexte uniquement."], "S5": ["INRS ED 6292, Interventions à proximité des réseaux électriques aériens (déc. 2017)", "https://www.inrs.fr/dam/inrs/CataloguePapier/ED/TI-ED-6292.pdf", "Lu pour les distances (§3.1, §3.2.1) ; aucune conduite à tenir en cas de contact d'engin."], "S6": ["Arrêté du 15 février 2012 modifié, art. 1 et art. 7 IV", "https://aida.ineris.fr/reglementation/arrete-150212-pris-application-chapitre-iv-titre-v-livre-v-code-lenvironnement", "Page AIDA/INERIS tronquée à l'article 13."], "S7": ["Arrêté du 22 décembre 2015, art. 2 (modifié par l'arrêté du 26 octobre 2018)", "https://aida.ineris.fr/reglementation/arrete-221215-relatif-controle-competences-personnes-intervenant-travaux-a-proximite", "Page AIDA/INERIS."], "S8": ["Code de l'environnement R554-22, R554-26, R554-31 (pages OPPBTP)", "https://content.preventionbtp.fr/pdf/droit_de_la_prevention/article-r554-31-du-code-de-l-environnement-aipr.pdf", "Lu via OPPBTP ; Légifrance inaccessible depuis l'environnement de production."], "S9": ["Fiche programme Consul Team « AIPR Module Opérateur »", "", "Document fourni par le formateur."], "S10": ["Guichet unique des réseaux et canalisations (INERIS)", "https://www.reseaux-et-canalisations.ineris.fr/", "Portail officiel."], "S11": ["BARPI/DGPR, Flash ARIA « Travaux à proximité des réseaux souterrains », juin 2026", "https://www.faceaurisque.com/wp-content/uploads/2026/06/Flash-Aria-Barpi-Travaux-realises-a-proximite-des-reseaux-souterrains-maitriser-le-risque-dendommagement-juin-2026_compressed.pdf", "Lu en entier via l'outil de lecture ; pas de numérotation de pages."], "S12": ["Base ARIA (BARPI), fiches 61637, 61751 et 49925", "https://www.aria.developpement-durable.gouv.fr/", "Fiches lues individuellement, sauf la fiche 34280 (non accessible : citée d'après S11)."], "S13": ["INRS, Travail & Sécurité n° 871, juin 2025, dossier réseaux", "https://web4d.proto.inrs.fr/dam/inrs/CataloguePapier/TS/TI-TS871page12.pdf", "Extrait d'une page lu ; accident de nacelle cité sans date."], "S14": ["Ministère de la Transition écologique, fiche réforme anti-endommagement, 2016", "https://www.dictservices.fr/wp-content/uploads/2016/03/2_Fiche_reforme_anti-endommagement_2016-2_Fiche_reforme_anti-endommagement_2016.pdf", "Chiffres 2007 et 2015, donc anciens ; copie hébergée par un prestataire."], "S15": ["Tendance Ouest, fuite de gaz à Sotteville-lès-Rouen, 14/11/2011", "https://www.tendanceouest.com/actualite-39562-importante-fuite-de-gaz-a-sotteville", "Article de presse local, seul exemple de presse vérifié."]}, "foundation": [["Qu'est-ce qu'un réseau ?", "Un réseau est un ouvrage qui transporte quelque chose : de l'électricité, du gaz, de l'eau, de la chaleur, des signaux de télécommunication, des eaux usées. Il est géré par un exploitant (une entreprise ou une collectivité).", "Quand vous voyez un tampon, un coffret, une borne ou un poteau, demandez-vous : à qui est-ce, et que transporte-t-il ?", "S2 §3 ; S1 §1.3"], ["Enterré, aérien, affleurant", "Un réseau peut être enterré, aérien (câbles sur poteaux ou pylônes, en façade) ou affleurant : ce que l'on voit en surface d'un réseau enterré, comme un regard, une vanne, un coffret ou une borne.", "Un affleurant montre que le réseau existe, mais ne montre pas exactement où il passe sous le sol.", "S2 §3.1.2, §3.3.3, §3.7.1"], ["Sensible ou non sensible", "Un réseau est dit sensible pour la sécurité quand son endommagement peut avoir des conséquences graves : hydrocarbures, produits chimiques, gaz combustibles, vapeur et fluides caloporteurs, lignes électriques et éclairage public (hors basse tension aérienne isolée), transports guidés, transport pneumatique de déchets, digues. Télécommunications, eau potable, incendie et assainissement sont non sensibles, sauf si l'exploitant les enregistre comme sensibles.", "Sur un réseau sensible, vous ne démarrez pas sans le récépissé de DICT, et un endommagement déclenche la règle des 4 A.", "S3 p. 6-7 ; S1 §1.1"], ["Rigide ou flexible", "La réglementation distingue les ouvrages rigides et les ouvrages flexibles. La précision de position n'est pas la même en classe A : 40 cm pour un ouvrage rigide, 50 cm pour un ouvrage flexible.", "Un réseau flexible déplacé de plus de 10 cm doit être signalé à l'exploitant.", "S6 art. 1 ; S8 R554-31"], ["Un plan n'est pas la réalité", "Les plans des exploitants sont approximatifs. Ils portent une classe de précision : A (très fiable), B (approximatif), C (peu fiable ou position inconnue). Même en classe A, la position peut varier de 40 à 50 cm.", "Le plan indique une zone où chercher, jamais un trait sur lequel creuser en confiance.", "S6 art. 1"], ["Les quatre acteurs", "Le responsable de projet décide les travaux. L'exécutant des travaux les réalise. L'exploitant gère le réseau. Le guichet unique est l'annuaire officiel qui dit quels exploitants ont des réseaux près du chantier.", "L'opérateur travaille pour l'exécutant : c'est lui qui doit vous informer.", "S1 §1.3"], ["Le vocabulaire du chantier", "L'emprise est la zone occupée par les travaux. La tranchée ou la fouille est le trou que l'on creuse. Le fuseau est la bande autour du tracé supposé d'un réseau, où la position réelle est incertaine. Le marquage-piquetage est le repérage au sol, par peinture ou piquets, de l'emplacement supposé des réseaux.", "Si le marquage a disparu, on ne continue pas à l'aveugle : on prévient l'encadrement.", "S2 p. 8 ; S3 p. 36-37"], ["Se renseigner avant, s'arrêter dans le doute", "Toute la réglementation tient en deux réflexes : se renseigner avant de travailler (guichet unique, DT, DICT, récépissés, marquage) et s'arrêter dès que la réalité ne correspond pas aux informations.", "C'est ce que l'examen vérifie, sous forme de situations.", "S1 §3.4"], ["Les sigles à connaître", "AIPR : autorisation d'intervention à proximité des réseaux. DT : déclaration de projet de travaux. DICT : déclaration d'intention de commencement de travaux. ATU : avis de travaux urgents. IC : investigations complémentaires. Cerfa : formulaire officiel. Le glossaire du site les reprend tous.", "En cas de doute sur un mot, le glossaire est dans le menu.", "S1 ; S3"], ["Comment lire ce support", "Chaque séquence commence par une situation. Vous formulez votre décision, puis vous comparez avec le corrigé. Les repères sont sourcés ; quand une information n'a pas pu être vérifiée, elle est signalée comme telle.", "Ouvrez les séquences dans l'ordre si vous débutez.", "S9"]], "modules": [{"id": 1, "title": "Mon rôle d'opérateur", "scope": "Opérateur", "goal": "Situer mon rôle, mes obligations et celles des autres acteurs.", "scenario": "Vous conduisez une pelle sur un chantier de voirie. Le chef de chantier dit : « Tout est déclaré, vous pouvez y aller. »", "glance": [["Qui", "Responsable de projet, exécutant, exploitant"], ["Quoi", "DT, DICT, récépissés, marquage"], ["Moi", "Je suis informé, je vérifie, je m'arrête dans le doute"]], "alert": null, "sections": [["L'opérateur, c'est qui ?", "Le guide pratique FFB, FNTP, OPPBTP et SGAMbtp désigne par opérateur le personnel qui intervient pour l'exécutant en tant que conducteur d'engins. Sur un chantier de travaux urgents, tout personnel qui intervient en terrassement ou à l'approche des réseaux doit détenir l'AIPR. [S3 p. 14, 43]"], ["Les trois profils de l'AIPR", "Concepteur : il intervient pour le responsable de projet. Encadrant : il intervient pour l'exécutant, comme conducteur ou chef de chantier. Opérateur : il conduit les engins. L'attestation de concepteur couvre aussi les profils encadrant et opérateur ; celle d'encadrant couvre opérateur. [S3 p. 14 ; S7, à reconfirmer sur Légifrance]"], ["Qui fait quoi", "- Le **responsable de projet** décide les travaux, fait la DT et fait procéder au marquage-piquetage.\n- L'**exécutant des travaux** réalise, fait la DICT, conserve les récépissés et le compte rendu de marquage sur le chantier et informe son personnel.\n- L'**exploitant** gère le réseau et répond à chaque déclaration par un récépissé, même s'il n'est pas concerné.\n[S1 §3.2, §3.4, §3.5]"], ["Ce que l'exécutant vous doit", "L'exécutant informe son personnel de la localisation des ouvrages repérés et des mesures de prévention à appliquer, et vérifie sa formation et son AIPR. Il doit aussi veiller à ce que les dispositifs de sécurité de l'emprise restent accessibles et intacts. [S8 R554-31 ; S1 §3.4 j]"], ["Mon AIPR : qui la délivre, combien de temps", "L'employeur délivre l'AIPR, notamment sur la base d'une attestation de compétences après un QCM, d'un CACES en cours de validité ou d'un diplôme de moins de 5 ans. La validité ne dépasse pas la validité du justificatif, ni 5 ans pour une attestation de QCM. [S3 p. 15-16 ; S7]"]], "decision": "Le chef de chantier dit : « Tout est déclaré ». Que demandez-vous à voir avant de commencer ?", "answer": "Les récépissés de DICT et le compte rendu de marquage-piquetage, qui doivent se trouver sur le chantier, ainsi que l'information sur la localisation des réseaux et les mesures de prévention. Sur un réseau sensible, on ne démarre pas sans le récépissé de DICT. [S1 §3.4 e, j, m]", "check": ["Récépissés et compte rendu de marquage présents sur le chantier", "On m'a dit où sont les réseaux et les organes de sécurité", "Mon AIPR est en cours de validité"], "visuals": ["V01", "V09"], "facil": "Demander au groupe : « Qui, sur ce chantier, est responsable de quoi ? » avant d'ouvrir les sections."}, {"id": 2, "title": "Reconnaître les réseaux sur le terrain", "scope": "Opérateur", "goal": "Identifier les familles de réseaux enterrés et aériens et leurs repères visibles.", "scenario": "Une borne jaune, un tampon rond et un coffret métallique sont visibles près de la zone de fouille.", "glance": [["Électricité", "Grillage avertisseur rouge, coffrets, postes"], ["Gaz", "PE noir à bandes jaunes, grillage jaune, bornes"], ["Autres", "Chaleur, télécoms, eau, assainissement"]], "alert": ["Le grillage avertisseur n'est pas systématique", "Son absence ne prouve pas l'absence de réseau : il manque notamment sur les anciens ouvrages et les poses sans tranchée. [S2 §3.1.2 note 4, §3.3.3]"], "sections": [["Enterré, aérien, affleurant", "Un réseau peut courir sous le sol, dans l'air, ou être signalé en surface par des affleurants : coffrets, postes, boîtes, tampons, regards, vannes, bornes. [S2 §3.1.2, §3.7.1]"], ["Sensibles et non sensibles", "Réseaux sensibles : hydrocarbures, produits chimiques, gaz combustibles, vapeur et fluides caloporteurs, lignes électriques et éclairage public (hors basse tension aérienne isolée), transports guidés, transport pneumatique de déchets, digues. Non sensibles : télécommunications, eau potable et incendie, assainissement. L'exploitant peut classer certains non sensibles comme sensibles. [S3 p. 6-7]"], ["Électricité", "Aérien : conducteurs nus ou isolés sur poteaux ou pylônes, parfois en façade ; en basse tension, le câble peut être torsadé. Souterrain : profondeur courante de 0,60 à 0,85 m, avec un grillage avertisseur rouge à 20 cm au-dessus du câble. Affleurants : coffrets, postes, boîtes, tampons, remontées aéro-souterraines. [S2 §3.1.2]"], ["Gaz", "Transport : aucun objet ne signale précisément le tracé ; des bornes, balises ou plaques jaunes indiquent seulement la proximité, souvent déportées. Distribution : canalisations en polyéthylène à plus de 70 %, noires avec bandes longitudinales jaunes et marquage « PE » tous les mètres, grillage avertisseur jaune à 20 cm au-dessus ; les plus anciens PE n'ont pas de bande jaune. Affleurants : regards, coffrets, bornes, robinets encastrés en façade. [S2 §3.3.3, §3.4.1, §3.4.2]"], ["Chaleur et froid", "Aucun objet spécifique : seuls les regards en trottoir ou chaussée sont visibles, souvent déportés. Grillage avertisseur violet, non systématique. Profondeur minimale de 40 cm. [S2 §3.6.3, §3.6.4]"], ["Télécommunications", "Chambres souterraines à plaques au logo de l'exploitant, armoires de sous-répartition sur trottoir, poteaux métalliques ou en bois. Conduites majoritairement en PVC regroupées en paquets. [S2 §3.7.1, §3.7.3, §3.7.4]"], ["Eau potable", "Fonte dans la plupart des cas en zone urbaine ; acier, béton, PE, PVC, plomb et amiante-ciment existent aussi. Branchements usuellement en polyéthylène haute densité à bandes bleues. Bouches d'incendie, bouches à clé, ventouses, vidanges, compteurs et regards sont des repères. [S2 §3.8.2, §3.8.3]"], ["Assainissement et hydrocarbures", "Ces familles ne figurent pas dans la partie du fascicule 2 que nous avons pu lire. Le formateur les présente à partir des documents de l'exploitant. [Non vérifié]"]], "decision": "Vous voyez en fouille un grillage plastique rouge. Que concluez-vous, et que faites-vous ?", "answer": "Un grillage avertisseur rouge signale en principe un câble électrique situé environ 20 cm plus bas. J'arrête la fouille à cet endroit, je préviens l'encadrement et je ne perce pas. Un réseau électrique est sensible. [S2 §3.1.2 ; S3 p. 6]", "check": ["Je sais ce que signalent bornes, tampons, coffrets", "Je ne conclus pas à l'absence de réseau faute de grillage", "Dans le doute, je m'arrête"], "visuals": ["V06"], "facil": "Projeter une photo de fouille (à fournir) et demander de nommer les repères. Ne jamais citer de couleur de marquage au sol sans la source."}, {"id": 3, "title": "Mesurer les risques", "scope": "Opérateur", "goal": "Relier chaque réseau à ses dangers et aux atteintes possibles.", "scenario": "Vous devez travailler avec une pelle sous une ligne électrique aérienne, à côté d'une conduite de gaz enterrée.", "glance": [["Danger", "Énergie présente dans le réseau"], ["Exposition", "Contact, rupture, fuite, amorçage"], ["Prévention", "Distance, arrêt, alerte, pas d'intervention"]], "alert": ["Ligne électrique : risque mortel quelle que soit la tension", "Tout contact ou amorçage avec une ligne électrique présente un risque mortel. [S2 §3.1.4]"], "sections": [["Électricité", "Le risque est mortel quelle que soit la tension. L'induction peut atteindre des pièces conductrices à plusieurs centaines de mètres de lignes haute tension. En souterrain, l'approche sans visibilité est la principale situation à risque, avec un risque d'arc. [S2 §3.1.4, §3.1.6]"], ["Lignes aériennes : distances", "Les distances minimales de sécurité sont de 3 m pour une tension inférieure à 50 000 V, et de 5 m à partir de 50 000 V ; elles s'appliquent aussi aux engins, outils et matériaux manipulés. Les détecteurs d'approche ne sont pas des distances de sécurité. Un contact peut aussi faire exploser des pneumatiques. [S5 §2.4, §3.1, §3.2.1, §4 ; S3 p. 30]"], ["Gaz", "Transport : haute pression ; une fuite à fort bruit peut s'enflammer, avec projections et brûlures à grande distance. Distribution : le polyéthylène fond dès 120 °C en cas de point chaud, avec risque de fuite enflammée ; une fuite peut migrer dans le sol vers les immeubles. GPL : gaz plus lourd que l'air, il s'accumule dans les points bas (caves, regards, fouilles ouvertes). [S2 §3.3.5, §3.4.4, §3.5.2]"], ["Chaleur et froid", "Toute atteinte à l'intégrité (caniveau, calorifuge, enveloppe) doit être considérée comme une agression. Risques : vaporisation, brûlures, effondrement de dalles, percement de l'acier. [S2 §3.6.6]"], ["Eau potable", "Projections de fragments, inondation, jets puissants au-delà de 100 mm, déstabilisation des butées par affouillement ou décompression. [S2 §3.8.4]"], ["Télécommunications", "Interruption de services sensibles, effondrement, écrasement sous engins lourds, accumulation de gaz dans les chambres. [S2 §3.7.5]"], ["Les atteintes aux réseaux", "Le guide pratique cite, pour 2019, plus de 19 000 dommages lors de travaux au voisinage de 4,5 millions de kilomètres de réseaux en France, soit 64 par jour ouvrable. Le guide ne cite pas de source primaire pour ce chiffre : il est donné à titre indicatif. [S3 p. 5]"]], "decision": "Vous devez positionner une nacelle sous une ligne dont vous ignorez la tension. Que faites-vous ?", "answer": "Je ne m'approche pas et je demande à l'encadrement de faire établir la tension et les distances applicables : 3 m en dessous de 50 000 V, 5 m à partir de 50 000 V, engin et charge compris. [S5 §3.1]", "check": ["Distance de la ligne vérifiée, engin et charge compris", "Réseau enterré identifié et marqué", "Plan d'arrêt défini en cas d'incident"], "visuals": ["V07"], "facil": "Faire dessiner par un stagiaire la zone de 3 m autour d'une ligne sur un tableau."}, {"id": 4, "title": "Respecter les repères : marquage, signes et terrain", "scope": "Opérateur", "goal": "Comprendre le marquage-piquetage et les signes avertisseurs, et ce que j'ai à faire pour les respecter.", "scenario": "En arrivant sur le chantier, vous constatez que la peinture de marquage est en partie effacée par la circulation.", "glance": [["Marquage", "Fait par le responsable de projet, maintenu par l'exécutant"], ["Compte rendu", "Signé, remis à l'exécutant, gardé sur le chantier"], ["Moi", "Je respecte, je signale ce qui s'efface"]], "alert": ["Marquage effacé : on ne continue pas à l'aveugle", "L'exécutant maintient le marquage en bon état. Si le marquage disparaît, je préviens l'encadrement avant de poursuivre. [S1 §3.4 f]"], "sections": [["Le marquage-piquetage", "Le responsable de projet procède ou fait procéder, sous sa responsabilité et à ses frais, au marquage-piquetage. Il est réalisé au plus près du démarrage. Il est obligatoire pour tout élément souterrain situé dans l'emprise ou à moins de 2 m de l'emprise en planimétrie. Un compte rendu signé est remis à l'exécutant, et le marquage est maintenu pendant toute la durée du chantier. [S1 §3.2 i ; S3 p. 36-37 ; S4 p. 7]"], ["Combien de temps tient un marquage", "Les marquages sont naturellement dégradables dans un délai maximal de six mois. Un chantier long peut donc exiger de les refaire. [S6 art. 7 IV]"], ["Les couleurs du marquage au sol", "Le marquage-piquetage reprend les couleurs des grillages avertisseurs. Annexe 4 de l'ED 6164 [S4 p. 32] :\n- **rouge** : électricité (distribution et transport), éclairage public ;\n- **jaune** : gaz combustibles, hydrocarbures liquides ou liquéfiés ;\n- **orange** : gaz de l'air liquide, produits chimiques ;\n- **bleu** : eau potable ;\n- **marron** : assainissement ;\n- **violet** : chauffage et climatisation urbains ;\n- **vert** : télécommunications ;\n- **blanc** : équipements routiers dynamiques en très basse tension ;\n- **rose** : réseaux de natures différentes et très proches les uns des autres.\nAttention : cette édition de l'ED 6164 date d'avril 2014. Le formateur vérifie que le code est toujours celui du fascicule 3 en vigueur. [Non vérifié sur le fascicule 3]"], ["Les signes avertisseurs du sous-sol", "Grillage avertisseur rouge pour l'électricité, jaune pour le gaz, violet pour la chaleur et le froid, placé à 20 cm au-dessus de l'ouvrage pour l'électricité et le gaz. Les branchements d'eau potable en PEHD portent des bandes bleues. Ces dispositifs ne sont pas systématiques. [S2 §3.1.2, §3.4.2, §3.6.4, §3.8.2]"], ["Les moyens de repérage visibles", "Bornes, balises et plaques jaunes pour le gaz de transport (proximité, souvent déportées), regards, coffrets, vannes, bouches à clé, plaques au logo de l'exploitant pour les télécoms. [S2 §3.3.3, §3.7.1, §3.8.3]"], ["Le terrain et l'environnement", "Le respect du terrain et de l'environnement fait partie du programme de la journée ; ce point est traité avec le formateur à partir des consignes du chantier. EPI et EPC : leur choix dépend du chantier et des consignes de l'employeur, et n'est pas détaillé dans les sources lues. [S9 ; Non vérifié]"]], "decision": "Le marquage est effacé sur 5 mètres devant votre engin. Que faites-vous ?", "answer": "Je m'arrête et je préviens l'encadrement. Le marquage doit être maintenu en bon état par l'exécutant, et je ne poursuis pas sans repère. [S1 §3.4 f]", "check": ["Marquage visible sur toute l'emprise", "Compte rendu de marquage sur le chantier", "Je connais les signes avertisseurs de ma zone"], "visuals": ["V11", "V06", "V08"], "facil": "Montrer la photo du marquage au sol et demander : qui l'a fait faire, qui le maintient, que fait-on s'il s'efface ?"}, {"id": 5, "title": "Se renseigner avant : guichet unique, DT, DICT", "scope": "Opérateur", "goal": "Comprendre le circuit des déclarations et savoir ce que je dois trouver sur le chantier.", "scenario": "Le chef de chantier vous demande de commencer. Vous ne savez pas si les réponses des exploitants sont arrivées.", "glance": [["DT", "Responsable de projet, avant le marché"], ["DICT", "Exécutant, avant les travaux"], ["Récépissé", "Réponse de l'exploitant"]], "alert": ["Réseau sensible : pas de démarrage sans récépissé de DICT", "L'exécutant ne démarre pas avant d'avoir reçu les récépissés de DICT des exploitants de réseaux sensibles, ni avant les rendez-vous sur site demandés. [S1 §3.4 e]"], "sections": [["Le guichet unique", "C'est l'annuaire officiel des réseaux. On le consulte avant d'envoyer une DT ou une DICT : il indique les exploitants concernés autour du chantier. [S1 §5.1 ; S10]"], ["La DT", "Le responsable de projet l'établit avant le marché. Elle est envoyée à chaque exploitant avec le formulaire Cerfa DT-DICT et le plan de l'emprise. L'exploitant répond dans un délai de 9 jours, ou de 15 jours si la DT n'est pas dématérialisée, jours fériés non compris. [S1 §5.3 ; S8 R554-22]"], ["La DICT", "L'exécutant l'établit avant de commencer. L'exploitant répond dans un délai de 7 jours, ou de 9 jours si elle n'est pas dématérialisée, jours fériés non compris. Il doit répondre même s'il n'est pas concerné. [S1 §3.4 b, §3.5 l ; S8 R554-26]"], ["Les durées de validité", "La DT doit être renouvelée si le marché est signé plus de 3 mois après la consultation du guichet unique. La DICT doit être renouvelée si les travaux ne commencent pas dans les 3 mois, s'ils sont interrompus plus de 3 mois, ou si leur durée dépasse 6 mois ou la durée annoncée. Pas de DICT si un exploitant a répondu « non concerné » à une DT de moins de 3 mois. [S3 p. 17, 26, 30, 33]"], ["Absence de réponse", "En l'absence de réponse, l'exécutant envoie une relance en recommandé. Pour un réseau non sensible, les travaux peuvent démarrer 2 jours ouvrés après cette relance ; pour un réseau sensible, ils ne démarrent pas. [S3 p. 32]"], ["Ce qui doit être sur le chantier", "Les DICT, les récépissés, les plans, les recommandations et le compte rendu de marquage-piquetage. [S1 §3.4 m ; S3 p. 35]"]], "decision": "Le récépissé de DICT d'un exploitant de gaz n'est pas arrivé ; le chef de chantier dit qu'il l'est « sans doute ». Que répondez-vous ?", "answer": "Le gaz combustible est un réseau sensible : on ne démarre pas sans récépissé de DICT. Je demande à voir le récépissé et je n'engage pas l'engin tant qu'il n'est pas sur le chantier. [S1 §3.4 e ; S3 p. 6, 32]", "check": ["Récépissés présents", "DICT encore valable (moins de 3 mois avant démarrage)", "Pas de démarrage sur réseau sensible sans récépissé"], "visuals": ["V02"], "facil": "Faire placer par le groupe les 6 étapes de la frise dans le bon ordre, cartes en main."}, {"id": 6, "title": "Un plan n'est pas la réalité : précision et techniques", "scope": "Opérateur", "goal": "Comprendre la précision des plans et ses conséquences sur la façon de travailler.", "scenario": "Le plan indique une canalisation à 1 m du bord de la fouille. Le plan est de classe C.", "glance": [["Classe A", "Position fiable à 40 cm (rigide) ou 50 cm (flexible)"], ["Classe B", "Jusqu'à 1,5 m d'incertitude"], ["Classe C", "Plus de 1,5 m, ou inconnue"]], "alert": null, "sections": [["Les trois classes de précision", "Classe A : incertitude inférieure ou égale à 40 cm pour un ouvrage rigide, 50 cm pour un ouvrage flexible. Classe B : au-delà de A et jusqu'à 1,5 m, 1 m pour les branchements. Classe C : plus de 1,5 m, ou exploitant incapable de fournir la localisation. [S6 art. 1]"], ["Le fuseau de précaution", "Le fascicule 2 retient un fuseau de 3 mètres centrés sur le tracé théorique, 2 m pour les branchements. C'est dans ce fuseau que la position réelle est incertaine et que les techniques de travail doivent être adaptées. [S2 p. 8-9]"], ["Quand la classe A sera partout", "Selon le guide pratique de 2022, la classe A est exigée pour les réseaux sensibles depuis le 1er janvier 2020 en unité urbaine et à partir du 1er janvier 2026 hors unité urbaine ; pour les non sensibles, à partir du 1er janvier 2026 en unité urbaine et du 1er janvier 2032 hors unité urbaine. Des plans en classe B ou C peuvent donc subsister ; le formateur vérifie l'état actuel. [S3 p. 11]"], ["Les investigations complémentaires", "Quand le plan n'est pas assez précis, le responsable de projet peut devoir faire réaliser des investigations complémentaires par un prestataire certifié, qui garantit au minimum la classe A. C'est obligatoire pour un projet en unité urbaine avec au moins un réseau sensible en classe B ou C. [S1 §3.2 c, §3.9 ; S3 p. 19]"], ["Les techniques douces", "Le guide pratique renvoie au fascicule 2 pour les techniques dites « douces » à employer dans la zone d'approche, et le fascicule 2 en donne la définition. Les règles détaillées de terrassement (chapitre 5) n'ont pas pu être lues : elles sont présentées par le formateur. [S3 p. 23-24 ; S2 p. 10 ; Non vérifié]"], ["Quelques règles propres au gaz, à l'eau, aux télécoms", "Gaz : au moins 20 cm avec tout autre réseau, pas de source de chaleur non maîtrisée près du PE ou du plomb, ouverture préalable pour un travail sans tranchée en cas d'incertitude. Eau : fouilles blindées ou boisées, précautions à moins de 5 m des canalisations de 300 mm et plus. Télécoms : au moins 5 cm avec les autres réseaux. Chaleur : profondeur minimale de 40 cm. [S2 p. 33, 36, 39, 42]"]], "decision": "Le plan de classe C place une conduite à 1 m de votre fouille. Que faites-vous ?", "answer": "Un plan de classe C n'est pas fiable à plus de 1,5 m. Je ne creuse pas en confiance : je préviens l'encadrement qui décide des suites avec le responsable de projet (investigations, techniques douces). [S6 art. 1 ; S2 p. 8-10]", "check": ["Je connais la classe du plan", "Je sais où est le fuseau de précaution", "Techniques adaptées dans le fuseau"], "visuals": ["V03", "V04"], "facil": "Dessiner au sol à la craie un fuseau de 3 m et y placer une fausse conduite décalée."}, {"id": 7, "title": "Anomalie et situation inattendue", "scope": "Opérateur", "goal": "Reconnaître une anomalie et réagir par écrit et par l'arrêt, sans improviser.", "scenario": "Vous creusez : un câble apparaît, qui n'est pas sur le plan, à 60 cm de profondeur.", "glance": [["Constat", "Ce que je vois diffère du plan"], ["Arrêt", "Je suspends à cet endroit"], ["Compte rendu", "Je préviens, par écrit si possible"]], "alert": ["Réseau non identifié : je suspends", "En cas de découverte fortuite d'un réseau non identifié, ou de position non conforme aux réponses, l'exécutant sursoit aux travaux et prévient le responsable de projet. [S1 §3.4 k]"], "sections": [["Qu'est-ce qu'une anomalie", "Une anomalie est un écart entre le terrain et les informations reçues : réseau non repéré, position différente, dispositif avertisseur inattendu, branchement non cartographié. [S1 §3.4 k ; S3 p. 39-40]"], ["Que fait l'exécutant", "Il sursoit aux travaux concernés, y compris adjacents si un ouvrage sensible peut être concerné, signale l'anomalie par écrit et prévient le responsable de projet si la sécurité des salariés peut être menacée. Le responsable de projet analyse la situation et peut ordonner l'arrêt par écrit. [S1 §3.4 k, §3.2 k ; S3 p. 39-40]"], ["Les branchements", "Si le tracé réel d'un branchement s'écarte de plus d'un mètre de ce qui était prévu, le responsable de projet est prévenu. [S3 p. 39]"], ["Avant de commencer chaque jour", "Vérifier la présence des DICT, récépissés, plans et compte rendu de marquage ; informer le personnel ; vérifier l'accessibilité des vannes de coupure signalées ; vérifier le marquage ; repérer les branchements ; signaler par écrit toute incohérence entre terrain et plans. [S3 p. 35-36]"], ["Garder l'intégrité du réseau", "Sur un réseau de gaz découvert : ne pas marcher sur l'ouvrage ni l'utiliser comme marchepied, et écarter tout risque de chute d'objet sur les réseaux découverts. Sur une conduite d'eau : aucune pièce ne doit être manœuvrée ou poussée sans l'accord de l'exploitant. [S2 p. 33, 42]"]], "decision": "Un câble inconnu apparaît dans la tranchée. Un collègue propose de le décaler pour gagner du temps. Que répondez-vous ?", "answer": "Non. Je suspends le travail à cet endroit et je préviens l'encadrement. Déplacer un réseau, c'est intervenir dessus : c'est interdit. [S1 §3.4 k, §3.4 n]", "check": ["Je sais ce qu'est une anomalie", "Je suspends et je préviens", "Je n'interviens pas sur un réseau découvert"], "visuals": ["V02"], "facil": "Jouer la scène à deux : l'opérateur, le collègue pressé. Le groupe nomme les règles qui s'appliquent."}, {"id": 8, "title": "Incident, accident et travaux urgents", "scope": "Opérateur", "goal": "Appliquer la règle des 4 A et savoir ce qui est interdit après un endommagement.", "scenario": "Votre godet a accroché une conduite de gaz. Vous entendez un sifflement.", "glance": [["Arrêter", "Les engins"], ["Alerter", "Pompiers, puis exploitant"], ["Aménager · Accueillir", "Zone de sécurité, secours"]], "alert": ["Ne jamais intervenir sur un ouvrage endommagé", "En aucun cas l'exécutant n'intervient sur l'ouvrage endommagé : pas de colmatage, pas de remblaiement, pas de manœuvre de robinet. [S1 §3.4 n ; S3 p. 42]"], "sections": [["La règle des 4 A", "Arrêter les engins. Alerter les sapeurs-pompiers, puis l'exploitant. Aménager une zone de sécurité immédiate, si possible. Accueillir les secours et rester à leur disposition. [S1 §3.4 n ; S3 p. 42]"], ["Contact avec une ligne électrique", "En cas de contact électrique, il faut d'abord dégager l'engin du réseau avant de l'arrêter. [S3 p. 42 ; S1 §3.4 n]"], ["Même sans fuite", "Tout endommagement d'un réseau en service, même superficiel, se signale à l'exploitant dans les plus brefs délais, ainsi que tout déplacement accidentel de plus de 10 cm d'un ouvrage souterrain flexible. Un constat contradictoire est établi avec l'exploitant (Cerfa 14766*02). [S8 R554-31 ; S1 §3.4 l ; S3 p. 42]"], ["Que dit le fascicule 2 du gaz", "Une fuite de gaz avec sifflement ou bruit intense est un cas cité par le fascicule 2, qui renvoie son traitement au chapitre 8 (non lu). Le numéro d'urgence de l'exploitant figure dans ses réponses aux DICT et dans les coordonnées du guichet unique pour les réseaux sensibles. [S2 p. 33 ; S3 p. 29, 42]"], ["Les travaux urgents", "Quand l'urgence est justifiée par la sécurité, la continuité du service public ou la sauvegarde des personnes et des biens, ou en cas de force majeure, le commanditaire juge l'urgence, consulte le guichet unique et envoie un avis de travaux urgents (ATU) aux exploitants, éventuellement après coup ; il appelle systématiquement les exploitants de transport de matières dangereuses. L'exécutant ne fait intervenir que des personnes ayant une AIPR valide. [S1 §3.10, §3.11 ; S3 p. 43]"]], "decision": "Un sifflement de gaz après un coup de godet. Dans quel ordre agissez-vous ?", "answer": "J'arrête l'engin, j'alerte les sapeurs-pompiers puis l'exploitant, je fais éloigner et aménager une zone de sécurité si possible, et j'accueille les secours. Je ne colmate rien. [S1 §3.4 n]", "check": ["Je connais les 4 A dans l'ordre", "Je sais qui alerter, dans quel ordre", "Je n'interviens jamais sur le réseau"], "visuals": ["V05"], "facil": "Cartes des 4 A à remettre dans l'ordre, puis scène simulée de l'alerte (qui appelle qui, que dit-on)."}], "questions": [{"id": "Q01", "module": 5, "q": "Qui établit la DT (déclaration de projet de travaux) ?", "c": "Le responsable de projet", "d": ["L'exécutant des travaux", "L'exploitant du réseau", "Le conducteur d'engin"], "why": "La DT est établie par le responsable de projet, sous sa responsabilité.", "src": "S1 §5.3", "p": 0}, {"id": "Q02", "module": 5, "q": "Qui établit la DICT ?", "c": "L'exécutant des travaux", "d": ["Le responsable de projet", "L'exploitant du réseau", "Le guichet unique"], "why": "La DICT est établie par l'exécutant avant le début des travaux.", "src": "S1 §3.4 b", "p": 0}, {"id": "Q03", "module": 5, "q": "Qu'est-ce qu'un récépissé ?", "c": "La réponse de l'exploitant à une déclaration", "d": ["Le plan du chantier", "L'autorisation de travailler délivrée par la mairie", "L'attestation AIPR"], "why": "L'exploitant répond à chaque déclaration avec le formulaire de récépissé réglementaire.", "src": "S1 §3.5 k", "p": 0}, {"id": "Q04", "module": 6, "q": "Un exploitant qui n'a pas de réseau près du chantier doit-il répondre à la déclaration ?", "c": "Oui, il répond quand même", "d": ["Non, son silence vaut réponse", "Seulement si on le relance", "Seulement pour la DICT"], "why": "L'exploitant doit répondre même s'il n'est pas concerné.", "src": "S1 §3.5 l", "p": 0}, {"id": "Q05", "module": 5, "q": "Quel est le délai de réponse de l'exploitant à une DT dématérialisée ?", "c": "9 jours, jours fériés non compris", "d": ["24 heures", "30 jours", "3 mois"], "why": "Neuf jours, jours fériés non compris (quinze jours si la DT n'est pas dématérialisée).", "src": "S8 R554-22", "p": 0}, {"id": "Q06", "module": 5, "q": "Quel est le délai de réponse de l'exploitant à une DT envoyée sur papier ?", "c": "15 jours, jours fériés non compris", "d": ["5 jours", "9 jours", "60 jours"], "why": "Le délai est porté à quinze jours, jours fériés non compris.", "src": "S8 R554-22", "p": 0}, {"id": "Q07", "module": 5, "q": "Quel est le délai de réponse de l'exploitant à une DICT dématérialisée ?", "c": "7 jours, jours fériés non compris", "d": ["48 heures", "15 jours", "1 mois"], "why": "Sept jours, jours fériés non compris (neuf jours si non dématérialisée).", "src": "S8 R554-26", "p": 0}, {"id": "Q08", "module": 6, "q": "Classe de précision A, réseau rigide : quelle incertitude maximale sur la position ?", "c": "40 cm", "d": ["10 cm", "1,5 m", "3 m"], "why": "Classe A : incertitude inférieure ou égale à 40 cm pour un ouvrage rigide (50 cm s'il est flexible).", "src": "S6, art. 1", "p": 0}, {"id": "Q09", "module": 6, "q": "Classe de précision A, réseau flexible : quelle incertitude maximale ?", "c": "50 cm", "d": ["40 cm", "1 m", "2 m"], "why": "Classe A : 50 cm pour un ouvrage flexible.", "src": "S6, art. 1", "p": 0}, {"id": "Q10", "module": 6, "q": "Que signifie la classe B ?", "c": "Incertitude au-delà de la classe A, jusqu'à 1,5 m", "d": ["Position exacte garantie", "Incertitude supérieure à 1,5 m", "Réseau hors service"], "why": "Classe B : au-delà de A et jusqu'à 1,5 m (1 m pour les branchements).", "src": "S6, art. 1", "p": 0}, {"id": "Q11", "module": 6, "q": "Que signifie la classe C ?", "c": "Incertitude supérieure à 1,5 m, ou position non fournie", "d": ["Réseau de très bonne précision", "Réseau abandonné", "Réseau aérien uniquement"], "why": "Classe C : plus de 1,5 m, ou exploitant incapable de fournir la localisation.", "src": "S6, art. 1", "p": 0}, {"id": "Q12", "module": 4, "q": "Au bout de combien de temps au maximum un marquage-piquetage doit-il se dégrader naturellement ?", "c": "6 mois", "d": ["15 jours", "2 ans", "Il ne se dégrade jamais"], "why": "Les marquages sont naturellement dégradables dans un délai maximal de six mois.", "src": "S6, art. 7 IV", "p": 0}, {"id": "Q13", "module": 4, "q": "Qui garde les récépissés de DICT et le compte rendu de marquage-piquetage sur le chantier ?", "c": "L'exécutant des travaux", "d": ["L'exploitant", "Le client final", "Personne : on les envoie par courrier"], "why": "L'exécutant conserve récépissés et compte rendu de marquage sur le chantier.", "src": "S1 §3.4 m", "p": 0}, {"id": "Q14", "module": 5, "q": "Le récépissé de DICT d'un exploitant de réseau sensible n'est pas arrivé. Peut-on commencer à creuser ?", "c": "Non, on attend le récépissé", "d": ["Oui, si le plan semble clair", "Oui, après 24 h", "Oui, si l'on creuse à la main"], "why": "L'exécutant ne démarre pas avant d'avoir reçu les récépissés de DICT des exploitants de réseaux sensibles.", "src": "S1 §3.4 e", "p": 1}, {"id": "Q15", "module": 7, "q": "En terrassant, vous découvrez un réseau qui n'est pas sur les plans. Que faites-vous ?", "c": "Je suspends le travail et je préviens mon responsable", "d": ["Je continue en dégageant autour", "Je le déplace", "Je le recouvre pour ne pas perdre de temps"], "why": "Découverte fortuite d'un réseau non identifié : on sursoit aux travaux et on prévient.", "src": "S1 §3.4 k", "p": 1}, {"id": "Q16", "module": 7, "q": "Vous avez simplement égratigné le revêtement d'un réseau. Faut-il le signaler ?", "c": "Oui, tout endommagement, même superficiel", "d": ["Non, ce n'est pas grave", "Seulement s'il y a une fuite visible", "Seulement le lendemain"], "why": "Tout endommagement, même superficiel, est signalé à l'exploitant dans les plus brefs délais.", "src": "S1 §3.4 l ; R554-31", "p": 1}, {"id": "Q17", "module": 8, "q": "Un réseau flexible souterrain a été déplacé accidentellement. À partir de quel déplacement faut-il avertir l'exploitant ?", "c": "Plus de 10 cm", "d": ["Plus de 1 m", "Plus de 50 cm", "Seulement s'il est cassé"], "why": "Un déplacement accidentel de plus de 10 cm d'un ouvrage souterrain flexible se signale.", "src": "S8 R554-31", "p": 0}, {"id": "Q18", "module": 8, "q": "Un réseau sensible est endommagé. Que faire en premier ?", "c": "Arrêter les engins", "d": ["Réparer", "Prendre des photos", "Rappeler le client"], "why": "Règle des 4 A : le premier A est Arrêter les engins.", "src": "S1 §3.4 n", "p": 1}, {"id": "Q19", "module": 8, "q": "Après un endommagement de réseau sensible : qui alerter, et dans quel ordre ?", "c": "Les sapeurs-pompiers, puis l'exploitant", "d": ["L'exploitant, puis le client", "Le responsable de chantier uniquement", "Personne si aucun blessé"], "why": "Règle des 4 A : Alerter les sapeurs-pompiers, puis l'exploitant.", "src": "S1 §3.4 n", "p": 1}, {"id": "Q20", "module": 8, "q": "Une canalisation endommagée fuit légèrement. Peut-on essayer de colmater ?", "c": "Non, en aucun cas", "d": ["Oui, avec un collier", "Oui, si la fuite est petite", "Oui, avec l'accord d'un collègue"], "why": "En aucun cas l'exécutant n'intervient sur l'ouvrage endommagé.", "src": "S1 §3.4 n", "p": 1}, {"id": "Q21", "module": 8, "q": "Que veut dire le troisième A de la règle des 4 A ?", "c": "Aménager une zone de sécurité immédiate, si possible", "d": ["Appeler un ami", "Ajourner le chantier", "Archiver les documents"], "why": "Les 4 A : Arrêter, Alerter, Aménager, Accueillir.", "src": "S1 §3.4 n", "p": 0}, {"id": "Q22", "module": 4, "q": "Qui fait procéder au marquage-piquetage ?", "c": "Le responsable de projet, sous sa responsabilité", "d": ["Le conducteur d'engin", "L'exploitant, à ses frais", "La mairie"], "why": "Le responsable de projet procède ou fait procéder au marquage, à ses frais.", "src": "S1 §3.2 i", "p": 0}, {"id": "Q23", "module": 4, "q": "Le marquage-piquetage s'efface en partie sur le chantier. Qui doit le maintenir en bon état ?", "c": "L'exécutant des travaux", "d": ["Personne", "Le guichet unique", "Le client"], "why": "L'exécutant maintient le marquage en bon état.", "src": "S1 §3.4 f", "p": 0}, {"id": "Q24", "module": 8, "q": "Pour des travaux urgents, qui peut intervenir ?", "c": "Seulement des personnes titulaires d'une AIPR valide", "d": ["Tout le monde, c'est urgent", "Les seuls conducteurs d'engins", "Les stagiaires"], "why": "En travaux urgents, l'exécutant ne fait intervenir que des personnes ayant une AIPR valide.", "src": "S1 §3.11", "p": 0}, {"id": "Q25", "module": 8, "q": "L'avis de travaux urgents (ATU) peut-il être envoyé après coup ?", "c": "Oui, éventuellement a posteriori", "d": ["Jamais", "Seulement avec accord du maire", "Seulement le week-end"], "why": "Le commanditaire envoie l'ATU aux exploitants, éventuellement après coup.", "src": "S1 §3.10", "p": 0}, {"id": "Q26", "module": 1, "q": "Le responsable de projet peut-il être un particulier ?", "c": "Oui", "d": ["Non, seulement une entreprise", "Non, seulement une collectivité", "Oui, mais sans DT"], "why": "Le responsable de projet peut être un maître d'ouvrage public ou privé, y compris un particulier.", "src": "S1 §1.3", "p": 0}, {"id": "Q27", "module": 5, "q": "Avant d'envoyer une DT, que faut-il consulter ?", "c": "Le guichet unique", "d": ["Le voisinage", "Le cadastre seul", "Le fabricant des engins"], "why": "On consulte le guichet unique puis on envoie la DT à chaque exploitant indiqué.", "src": "S1 §5.1", "p": 0}, {"id": "Q28", "module": 5, "q": "Le marché est signé plus de trois mois après la consultation du guichet unique. Que se passe-t-il pour la DT ?", "c": "Elle doit être renouvelée", "d": ["Rien", "Elle est valable un an", "Elle est annulée sans suite"], "why": "La DT doit être renouvelée si le marché est signé plus de trois mois après la consultation.", "src": "S1 §5.3", "p": 0}, {"id": "Q29", "module": 5, "q": "Qui informe le personnel de la localisation des réseaux et des mesures de prévention ?", "c": "L'exécutant des travaux", "d": ["Le guichet unique", "Le client final", "L'inspection du travail"], "why": "L'exécutant informe son personnel de la localisation des ouvrages repérés et des mesures à appliquer.", "src": "S8 R554-31 ; S1 §3.4 j", "p": 0}, {"id": "Q30", "module": 1, "q": "Qui délivre l'AIPR au salarié ?", "c": "L'employeur", "d": ["Le centre d'examen", "La mairie", "Le guichet unique"], "why": "L'AIPR est délivrée par l'employeur, notamment sur la base de l'attestation de compétences.", "src": "S7 (à reconfirmer sur Légifrance)", "p": 0}, {"id": "Q31", "module": 1, "q": "Quelle est la durée de validité maximale d'une AIPR ?", "c": "5 ans", "d": ["1 an", "10 ans", "Illimitée"], "why": "La validité d'une AIPR ne dépasse pas cinq ans.", "src": "S7 (à reconfirmer sur Légifrance)", "p": 0}, {"id": "Q32", "module": 1, "q": "Combien de questions compte l'examen pour le profil opérateur ?", "c": "30", "d": ["10", "40", "80"], "why": "Trente questions pour les opérateurs ; quarante pour concepteurs et encadrants.", "src": "S7, art. 2", "p": 0}, {"id": "Q33", "module": 1, "q": "Combien de points faut-il pour réussir l'examen opérateur ?", "c": "36 points sur 60 (60 %)", "d": ["20 sur 60", "48 sur 60", "60 sur 60"], "why": "Seuil de 60 % : 36 sur 60 pour les opérateurs, 48 sur 80 pour concepteurs et encadrants.", "src": "S7, art. 2", "p": 0}, {"id": "Q34", "module": 1, "q": "Combien de points retire une mauvaise réponse à une question prioritaire ?", "c": "5 points", "d": ["1 point", "2 points", "Aucun"], "why": "Barème : +2 bonne réponse, 0 « ne sait pas », −1 mauvaise réponse, −5 mauvaise réponse prioritaire.", "src": "S7, art. 2", "p": 0}, {"id": "Q35", "module": 1, "q": "Combien rapporte « je ne sais pas » ?", "c": "0 point", "d": ["1 point", "−1 point", "−2 points"], "why": "« Ne sait pas » vaut 0 point, ce qui évite la perte d'une mauvaise réponse.", "src": "S7, art. 2", "p": 0}, {"id": "Q36", "module": 1, "q": "Qui peut demander la lecture à voix haute des questions pour un opérateur ?", "c": "L'employeur, dans sa commande", "d": ["Le stagiaire sur place", "Le surveillant", "Le formateur"], "why": "L'employeur nomme les opérateurs concernés dans la commande d'examen.", "src": "S7, art. 2", "p": 0}, {"id": "Q37", "module": 4, "q": "Combien de temps dure au maximum l'examen ?", "c": "1 heure", "d": ["15 minutes", "3 heures", "Pas de limite"], "why": "L'ensemble des questions doit être traité en une heure au plus.", "src": "S7, art. 2", "p": 0}, {"id": "Q38", "module": 1, "q": "Les dispositifs de sécurité situés dans l'emprise du chantier doivent-ils rester accessibles et intacts ?", "c": "Oui, l'exécutant y veille après chaque phase importante", "d": ["Non, on peut les déplacer", "Seulement la nuit", "Seulement pour le gaz"], "why": "L'exécutant veille à leur accessibilité et à leur intégrité.", "src": "S8 R554-31", "p": 0}, {"id": "Q39", "module": 2, "q": "Quelle est la couleur du grillage avertisseur d'un câble électrique enterré ?", "c": "Rouge", "d": ["Jaune", "Bleu", "Vert"], "why": "Le fascicule 2 décrit un grillage avertisseur rouge, à 20 cm au-dessus du câble. Il n'est pas systématique.", "src": "S2 §3.1.2", "p": 0}, {"id": "Q40", "module": 2, "q": "Quelle est la couleur du grillage avertisseur d'une canalisation de distribution de gaz ?", "c": "Jaune", "d": ["Rouge", "Violet", "Blanc"], "why": "Grillage avertisseur jaune à 20 cm au-dessus de la canalisation de gaz de distribution.", "src": "S2 §3.4.2", "p": 0}, {"id": "Q41", "module": 2, "q": "Quelle est la couleur du grillage avertisseur d'un réseau de chaleur ou de froid ?", "c": "Violet", "d": ["Rouge", "Jaune", "Bleu"], "why": "Le fascicule 2 cite un grillage avertisseur violet, non systématique, pour les réseaux de chaleur et de froid.", "src": "S2 §3.6.4", "p": 0}, {"id": "Q42", "module": 2, "q": "Vous ne voyez pas de grillage avertisseur dans la fouille. Peut-on en conclure qu'il n'y a pas de réseau ?", "c": "Non, le grillage n'est pas systématique", "d": ["Oui, c'est la preuve", "Oui, si le plan est ancien", "Oui, en dessous de 1 m"], "why": "Le grillage avertisseur manque notamment sur les anciens ouvrages et les poses sans tranchée.", "src": "S2 §3.1.2 note 4", "p": 1}, {"id": "Q43", "module": 2, "q": "À quelle hauteur au-dessus d'un câble électrique enterré se place le grillage avertisseur ?", "c": "À 20 cm environ", "d": ["À 5 cm", "À 1 m", "Directement au contact"], "why": "Le grillage rouge est décrit à 20 cm au-dessus du câble.", "src": "S2 §3.1.2", "p": 0}, {"id": "Q44", "module": 6, "q": "Quelle largeur de fuseau de précaution retient le fascicule 2 autour du tracé théorique d'un réseau ?", "c": "3 mètres centrés sur le tracé", "d": ["30 cm", "10 mètres", "1 mètre de chaque côté seulement"], "why": "Fuseau de 3 m centrés sur le tracé théorique, 2 m pour les branchements.", "src": "S2 p. 8", "p": 0}, {"id": "Q45", "module": 4, "q": "Jusqu'à quelle distance de l'emprise le marquage-piquetage est-il obligatoire pour les éléments souterrains ?", "c": "2 m en planimétrie", "d": ["50 cm", "10 m", "Seulement dans l'emprise"], "why": "Obligatoire dans l'emprise ou à moins de 2 m de l'emprise en planimétrie.", "src": "S3 p. 37 ; S4 p. 7", "p": 0}, {"id": "Q46", "module": 3, "q": "Quelle distance minimale respecter d'une ligne électrique aérienne de tension inférieure à 50 000 V ?", "c": "3 m", "d": ["50 cm", "1 m", "10 m"], "why": "Trois mètres sous 50 000 V, cinq mètres à partir de 50 000 V, y compris pour les engins et matériaux manipulés.", "src": "S5 §3.1, §3.2.1 ; S3 p. 30", "p": 1}, {"id": "Q47", "module": 3, "q": "Quelle distance minimale respecter d'une ligne aérienne de tension supérieure ou égale à 50 000 V ?", "c": "5 m", "d": ["3 m", "1,5 m", "20 m"], "why": "Cinq mètres à partir de 50 000 V.", "src": "S5 §3.1 ; S3 p. 30", "p": 1}, {"id": "Q48", "module": 3, "q": "Les détecteurs d'approche de lignes aériennes indiquent-ils des distances de sécurité ?", "c": "Non, leurs portées ne sont pas des distances de sécurité", "d": ["Oui, ils les remplacent", "Oui, sous 50 000 V", "Seulement la nuit"], "why": "L'INRS précise que les portées des détecteurs ne sont pas des distances de sécurité.", "src": "S5 §4", "p": 0}, {"id": "Q49", "module": 8, "q": "Un engin touche une ligne électrique. Quel réflexe est cité par le guide pratique ?", "c": "Dégager l'engin du réseau avant de l'arrêter", "d": ["Descendre immédiatement de la cabine", "Appeler le client", "Attendre que la ligne refroidisse"], "why": "En cas de contact électrique, on dégage d'abord l'engin du réseau, avant de l'arrêter.", "src": "S3 p. 42 ; S1 §3.4 n", "p": 1}, {"id": "Q50", "module": 2, "q": "Comment est une canalisation de distribution de gaz en polyéthylène la plus courante ?", "c": "Noire avec des bandes longitudinales jaunes", "d": ["Verte unie", "Rouge avec bandes blanches", "Grise sans marquage"], "why": "PE noir à bandes jaunes, marquage « PE » tous les mètres ; les plus anciens n'ont pas de bande jaune.", "src": "S2 §3.4.1", "p": 0}, {"id": "Q51", "module": 3, "q": "À partir de quelle température le polyéthylène du gaz fond-il, avec risque de fuite enflammée ?", "c": "120 °C", "d": ["20 °C", "500 °C", "1 000 °C"], "why": "Le polyéthylène fond dès 120 °C en cas de point chaud.", "src": "S2 §3.4.4", "p": 0}, {"id": "Q52", "module": 3, "q": "Quelle particularité a le GPL en cas de fuite ?", "c": "Plus lourd que l'air, il s'accumule dans les points bas", "d": ["Il s'envole immédiatement", "Il est sans risque dans une fouille", "Il est toujours visible"], "why": "Le GPL s'accumule dans les caves, regards non siphonnés et fouilles ouvertes.", "src": "S2 §3.5.2", "p": 0}, {"id": "Q53", "module": 2, "q": "Comment reconnaît-on les branchements d'eau potable en polyéthylène haute densité ?", "c": "À leurs bandes bleues", "d": ["À leurs bandes jaunes", "À leur grillage violet", "Ils n'ont aucun repère"], "why": "Les branchements sont usuellement en PEHD à bandes bleues.", "src": "S2 §3.8.2", "p": 0}, {"id": "Q54", "module": 2, "q": "Lequel de ces réseaux est considéré comme sensible pour la sécurité ?", "c": "Le gaz combustible", "d": ["L'eau potable", "L'assainissement", "Les télécommunications"], "why": "Gaz combustibles, hydrocarbures, produits chimiques, vapeur, lignes électriques, transports guidés… sont sensibles.", "src": "S3 p. 6-7", "p": 1}, {"id": "Q55", "module": 2, "q": "Qui peut classer un réseau non sensible comme sensible ?", "c": "Son exploitant", "d": ["Le chef de chantier", "L'opérateur", "La mairie seulement"], "why": "L'exploitant peut classer certains réseaux non sensibles comme sensibles.", "src": "S3 p. 7", "p": 0}, {"id": "Q56", "module": 5, "q": "La DICT est établie, puis les travaux ne commencent pas pendant 4 mois. Que faut-il faire ?", "c": "Renouveler la DICT", "d": ["Rien, elle est valable un an", "Envoyer un simple courriel", "Commencer sans rien changer"], "why": "La DICT est renouvelée si les travaux ne commencent pas dans les 3 mois.", "src": "S3 p. 17, 33", "p": 0}, {"id": "Q57", "module": 5, "q": "Pour un réseau non sensible, sans réponse à la DICT et après relance, quand peut-on démarrer ?", "c": "2 jours ouvrés après la relance", "d": ["Immédiatement", "Jamais", "Après 3 mois"], "why": "Sur un réseau non sensible, les travaux peuvent démarrer 2 jours ouvrés après la relance ; pas sur un réseau sensible.", "src": "S3 p. 32", "p": 0}, {"id": "Q58", "module": 8, "q": "Comment s'appelle le formulaire du constat contradictoire de dommage ?", "c": "Cerfa 14766*02", "d": ["Cerfa 14434", "Cerfa 14435", "Cerfa 14523"], "why": "Un constat contradictoire est établi avec l'exploitant (Cerfa 14766*02).", "src": "S3 p. 42 ; S2 p. 6-7", "p": 0}, {"id": "Q59", "module": 4, "q": "Le compte rendu de marquage-piquetage est remis par le responsable de projet à…", "c": "L'exécutant des travaux", "d": ["L'exploitant", "Au guichet unique", "Au client seulement"], "why": "Un compte rendu signé est remis à l'exécutant, qui le garde sur le chantier.", "src": "S3 p. 37 ; S1 §3.4 m", "p": 0}, {"id": "Q60", "module": 7, "q": "Le tracé réel d'un branchement s'écarte de plus d'un mètre de ce qui était prévu. Que faire ?", "c": "Prévenir le responsable de projet", "d": ["Ignorer", "Déplacer le branchement", "Attendre la fin du chantier"], "why": "Au-delà d'un mètre d'écart, on prévient le responsable de projet.", "src": "S3 p. 39", "p": 0}, {"id": "Q61", "module": 1, "q": "Qui est « l'opérateur » dans le guide pratique ?", "c": "Le conducteur d'engins qui intervient pour l'exécutant", "d": ["Le responsable de projet", "L'exploitant", "L'inspecteur du travail"], "why": "Opérateur : conducteur d'engins intervenant pour l'exécutant.", "src": "S3 p. 14", "p": 0}, {"id": "Q62", "module": 8, "q": "Pour des travaux urgents, qui doit détenir l'AIPR ?", "c": "Tout le personnel en terrassement ou à l'approche des réseaux", "d": ["Seulement le chef", "Personne", "Seulement les stagiaires"], "why": "Sur un chantier de travaux urgents, tout personnel en terrassement ou approche des réseaux doit l'avoir.", "src": "S3 p. 14, 43", "p": 0}, {"id": "Q63", "module": 1, "q": "Une attestation de QCM AIPR a une validité maximale de…", "c": "5 ans", "d": ["1 an", "2 ans", "10 ans"], "why": "La validité ne dépasse pas 5 ans pour une attestation de QCM.", "src": "S3 p. 15-16", "p": 0}, {"id": "Q64", "module": 4, "q": "Que faire si une partie du marquage-piquetage s'efface ?", "c": "Prévenir l'encadrement avant de poursuivre", "d": ["Continuer de mémoire", "Tracer soi-même un nouveau tracé", "Attendre la pluie"], "why": "L'exécutant maintient le marquage en bon état.", "src": "S1 §3.4 f", "p": 0}, {"id": "Q65", "module": 7, "q": "Sur un réseau de gaz découvert, que ne faut-il pas faire ?", "c": "Marcher dessus ou l'utiliser comme marchepied", "d": ["Le regarder", "Le signaler", "Le protéger des chutes d'objets"], "why": "Ne pas marcher sur un ouvrage gaz ni l'utiliser comme marchepied.", "src": "S2 p. 33", "p": 0}], "cases": [["Un câble inconnu dans la tranchée", "Vous creusez et un câble apparaît. Il n'est ni sur le plan ni sur le marquage.", "Je suspends le travail à cet endroit et je préviens mon responsable. Je ne le déplace pas, je ne le recouvre pas. Les travaux reprennent après analyse.", "S1 §3.4 k", 7, "Débutant"], ["Un coup de godet léger", "Votre godet frotte une canalisation. Rien ne fuit. Vous pensez que ce n'est pas grave.", "Je le signale quand même : tout endommagement, même superficiel, est signalé à l'exploitant dans les plus brefs délais, avec un constat contradictoire.", "S1 §3.4 l ; S8 R554-31", 8, "Débutant"], ["Un sifflement après un accrochage", "Un réseau de gaz est endommagé et siffle.", "Arrêter les engins ; alerter les sapeurs-pompiers puis l'exploitant ; aménager une zone de sécurité si possible ; accueillir les secours. Je ne tente pas de colmater.", "S1 §3.4 n", 8, "Essentiel"], ["Le marquage a disparu", "Une partie du marquage a été effacée par la circulation.", "Je préviens mon encadrant avant de continuer : l'exécutant maintient le marquage en bon état.", "S1 §3.4 f", 4, "Débutant"], ["Pas de récépissé sur le chantier", "On vous demande de commencer, mais le récépissé de DICT d'un exploitant de réseau sensible n'est pas là.", "On ne démarre pas avant de l'avoir reçu. Les récépissés doivent aussi se trouver sur le chantier.", "S1 §3.4 e, §3.4 m", 5, "Essentiel"], ["Un réseau flexible déplacé", "En remblayant, vous voyez qu'un câble souterrain flexible a été déplacé de plusieurs dizaines de centimètres.", "Au-delà de 10 cm, le déplacement est à signaler à l'exploitant, même sans casse visible.", "S8 R554-31", 8, "Intermédiaire"], ["Une intervention urgente", "Une urgence demande d'intervenir sans attendre. Un collègue sans AIPR veut aider.", "En travaux urgents, l'exécutant ne fait intervenir que des personnes ayant une AIPR valide. Le commanditaire consulte le guichet unique et envoie l'ATU, éventuellement après coup.", "S1 §3.10, §3.11 ; S3 p. 43", 8, "Intermédiaire"], ["Un plan de classe C", "Le plan fourni est de classe C.", "Plus de 1,5 m d'incertitude, ou position non fournie. Je ne me fie pas au tracé : je le dis à mon encadrant, qui décide des suites avec le responsable de projet.", "S6 art. 1", 6, "Intermédiaire"], ["Nacelle sous une ligne", "Vous devez installer une nacelle près d'une ligne électrique aérienne.", "Je respecte les distances minimales, engin et charge compris : 3 m sous 50 000 V, 5 m à partir de 50 000 V. Un détecteur ne remplace pas ces distances. Dans le doute, je ne m'approche pas.", "S5 §3.1, §4 ; S3 p. 30", 3, "Essentiel"], ["Un grillage rouge", "Un grillage plastique rouge apparaît dans la fouille.", "Il signale en principe un câble électrique environ 20 cm plus bas. J'arrête la fouille, je prévois l'encadrement, je ne perce pas.", "S2 §3.1.2", 2, "Débutant"], ["Contact avec une ligne", "Votre pelle touche une ligne électrique aérienne.", "Je dégage d'abord l'engin du réseau avant de l'arrêter, puis j'applique la règle des 4 A et j'alerte.", "S3 p. 42 ; S1 §3.4 n", 8, "Essentiel"], ["Une DICT ancienne", "Les travaux reprennent après quatre mois d'interruption.", "La DICT doit être renouvelée si les travaux sont interrompus plus de 3 mois : je demande à l'encadrant de vérifier avant de reprendre.", "S3 p. 17, 33", 5, "Intermédiaire"]], "tps": [{"id": "TP-A", "title": "Lire un plan et son marquage", "scope": "Opérateur", "material": "Un plan de réseaux d'exploitant, le compte rendu de marquage-piquetage, une zone marquée (réelle ou simulée) à fournir par le formateur.", "before": "Rappeler les classes de précision A, B, C et le fuseau de précaution de 3 m.", "steps": ["Repérer sur le plan les réseaux de l'emprise et leur classe.", "Retrouver au sol le marquage correspondant.", "Repérer l'écart éventuel entre plan et marquage.", "Dire à voix haute ce que l'on ferait et qui l'on préviendrait."], "stop": "Plan illisible, marquage absent ou contradictoire avec le plan : on s'arrête et on prévient.", "after": "Qu'est-ce qui rend un plan peu fiable ? Qui décide quand le plan et le terrain divergent ?", "evidence": ["Identifie les réseaux et leur classe", "Retrouve le marquage au sol", "Signale un écart", "Nomme la personne à prévenir"]}, {"id": "TP-B", "title": "Identifier les réseaux à partir des affleurants", "scope": "Opérateur", "material": "Photos ou affleurants réels fournis par le formateur (regard, coffret, borne, plaque).", "before": "Rappeler les repères des familles de réseaux (module 2).", "steps": ["Nommer la famille de réseau probable pour chaque repère.", "Dire ce qu'on ne peut pas savoir (tracé, profondeur).", "Dire quel risque est associé.", "Dire quelle information manque avant de creuser."], "stop": "Repère inconnu ou ambigu : on ne conclut pas, on demande.", "after": "Quel repère m'a trompé ? Que ne dit pas un affleurant ?", "evidence": ["Nomme la famille de réseau", "Reconnaît les limites du repère", "Associe un risque", "Demande l'information manquante"]}, {"id": "TP-C", "title": "Analyser les risques d'une zone de travail", "scope": "Opérateur", "material": "Une situation exposée in situ ou en photo par le formateur ; aucune situation inventée sans source.", "before": "Rappeler les risques par énergie (module 3) et les distances de 3 m et 5 m.", "steps": ["Lister les réseaux présents ou probables.", "Associer chacun à son danger.", "Identifier ce qui peut être touché par l'engin.", "Choisir la mesure et le point d'arrêt."], "stop": "Réseau non identifié, distance incertaine, marquage absent.", "after": "Quelle décision change si le plan est de classe C ?", "evidence": ["Liste les réseaux", "Associe danger et réseau", "Désigne le point d'arrêt", "Rend compte"]}, {"id": "TP-D", "title": "Reconnaître les matériels liés aux réseaux", "scope": "Opérateur", "material": "Matériels fournis par le formateur (détecteur, localisateur, marqueur, engin).", "before": "Rappeler que les portées des détecteurs ne sont pas des distances de sécurité.", "steps": ["Nommer le matériel.", "Dire à quoi il sert.", "Dire ce qu'il ne garantit pas.", "Dire qui est habilité à l'utiliser."], "stop": "Matériel inconnu ou usage incertain : on ne l'utilise pas.", "after": "Quelle fausse sécurité un matériel peut-il donner ?", "evidence": ["Nomme le matériel", "Dit sa limite", "Ne le confond pas avec une distance de sécurité"]}], "complements": [{"title": "Les trois profils de l'AIPR", "key": "Concepteur ⊃ encadrant ⊃ opérateur : l'attestation la plus haute couvre les autres.", "body": "L'AIPR est délivrée par l'employeur. Le concepteur intervient pour le responsable de projet, l'encadrant pour l'exécutant (conducteur ou chef de chantier), l'opérateur conduit les engins.", "headers": ["Profil", "Intervient pour", "Examen"], "rows": [["Concepteur", "Le responsable de projet", "40 questions"], ["Encadrant", "L'exécutant des travaux", "40 questions"], ["Opérateur", "Conducteur d'engins", "30 questions"]], "source": "S3 p. 14 ; S7 art. 2"}, {"title": "Délais et durées de validité", "key": "DT : 9 jours (15 sur papier). DICT : 7 jours (9 sur papier). Renouvellement : 3 mois.", "body": "Les délais s'entendent en jours, fériés non compris.", "headers": ["Document", "Délai de réponse", "Renouvellement"], "rows": [["DT", "9 j · 15 j sur papier", "Si le marché est signé plus de 3 mois après la consultation du guichet unique"], ["DICT", "7 j · 9 j sur papier", "Travaux non commencés sous 3 mois, interrompus plus de 3 mois, ou durée dépassant 6 mois ou la durée annoncée"], ["DT-DICT conjointe", "9 j · 15 j sur papier", "—"]], "source": "S8 R554-22, R554-26 ; S3 p. 17, 26, 30, 33"}, {"title": "Les réseaux en un tableau", "key": "Chaque famille a ses repères, ses dispositifs avertisseurs et ses risques.", "body": "Tableau de synthèse à partir du fascicule 2 (consolidé au 18 février 2024), chapitre 3.", "headers": ["Réseau", "Repères", "Avertisseur", "Risques"], "rows": [["Électricité", "Poteaux, pylônes, coffrets, postes ; câbles souterrains à 0,60–0,85 m", "Grillage rouge à 20 cm, non systématique", "Risque mortel ; arc ; induction"], ["Gaz transport", "Bornes, balises, plaques jaunes déportées ; haute pression", "Grillage jaune, non systématique", "Fuite à fort bruit, projections, brûlures à grande distance"], ["Gaz distribution", "PE noir à bandes jaunes ; regards, coffrets, robinets en façade", "Grillage jaune à 20 cm", "PE fond dès 120 °C ; fuite migrant vers les immeubles"], ["GPL", "Citernes, organes de coupure", "—", "Gaz lourd, accumulation en points bas"], ["Chaleur, froid", "Regards déportés ; acier calorifugé ; ≥ 40 cm", "Grillage violet, non systématique", "Vaporisation, brûlures, effondrement"], ["Télécoms", "Chambres à plaques, armoires, poteaux ; PVC en paquets", "—", "Coupure de services, effondrement"], ["Eau potable", "Bouches à clé, ventouses, compteurs ; fonte, PEHD à bandes bleues", "—", "Jets, inondation, affouillement"]], "source": "S2 §3.1 à 3.8"}, {"title": "Classes de précision et échéances", "key": "A : 40 cm (rigide) ou 50 cm (flexible) · B : jusqu'à 1,5 m · C : au-delà.", "body": "Pour les branchements, la limite B/C est à 1 m.", "headers": ["Classe", "Incertitude maximale", "Suite"], "rows": [["A", "40 cm (rigide) · 50 cm (flexible)", "Fiable"], ["B", "1,5 m (1 m branchements)", "Approximatif"], ["C", "Plus de 1,5 m, ou inconnue", "Peu fiable"]], "source": "S6 art. 1 ; S3 p. 10-11"}, {"title": "Lignes aériennes : distances et hauteurs", "key": "3 m sous 50 000 V · 5 m à partir de 50 000 V, engin et charge compris.", "body": "Les hauteurs minimales de lignes au-dessus du sol sont indiquées à titre de repère.", "headers": ["Élément", "Valeur"], "rows": [["Distance minimale sous 50 000 V", "3 m"], ["Distance minimale à partir de 50 000 V", "5 m"], ["BT nu / torsadé", "6 m / 4 m au-dessus du sol"], ["HTA", "8 m au-dessus d'une voie"], ["Télécoms", "3 m trottoir, 4 m terrain privé, 6 m traversée de route"]], "source": "S5 §3.1 ; S2 §3.1.2, §3.7.6"}, {"title": "Barème et conditions de l'examen", "key": "Opérateur : 30 questions, 36 points sur 60, 1 heure.", "body": "Les questions prioritaires représentent 10 % de l'examen.", "headers": ["Réponse", "Points"], "rows": [["Bonne réponse", "+2"], ["Je ne sais pas", "0"], ["Mauvaise réponse", "−1"], ["Mauvaise réponse à une question prioritaire", "−5"]], "source": "S7 art. 2"}, {"title": "Quelques chiffres sur les dommages", "key": "Chiffres à titre indicatif : le guide ne cite pas de source primaire.", "body": "Le guide pratique cite pour 2019 plus de 19 000 dommages (64 par jour ouvrable) lors de travaux au voisinage de 4,5 millions de kilomètres de réseaux, et environ 5 millions de DT et DICT par an.", "headers": ["Indicateur", "Valeur", "Source"], "rows": [["Dommages 2019", "Plus de 19 000 (64 par jour ouvrable)", "S3 p. 5"], ["Linéaire de réseaux", "4,5 millions de km", "S3 p. 5"], ["DT et DICT par an", "Environ 5 millions", "S3 p. 4-5"]], "source": "S3 p. 4-5"}], "visuals": [{"id": "V01", "title": "Qui fait quoi", "file": "V01.svg", "modules": [1], "alt": "Quatre acteurs : responsable de projet, exécutant, exploitant, guichet unique.", "ref": "S1 §1.3, §3.2, §3.4, §3.5", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 330\" role=\"img\" aria-label=\"Les quatre acteurs\"><rect class=\"bx\" x=\"8\" y=\"8\" width=\"344\" height=\"70\" rx=\"10\"/><circle class=\"dot\" cx=\"36\" cy=\"43\" r=\"18\"/><text class=\"dn\" x=\"36\" y=\"49\" text-anchor=\"middle\">RP</text><text class=\"t\" x=\"66\" y=\"34\">Responsable de projet</text><text class=\"s\" x=\"66\" y=\"56\">décide · fait la DT · fait faire le marquage</text><rect class=\"bx\" x=\"8\" y=\"88\" width=\"344\" height=\"70\" rx=\"10\"/><circle class=\"dot\" cx=\"36\" cy=\"123\" r=\"18\"/><text class=\"dn\" x=\"36\" y=\"129\" text-anchor=\"middle\">EX</text><text class=\"t\" x=\"66\" y=\"114\">Exécutant des travaux</text><text class=\"s\" x=\"66\" y=\"136\">réalise · fait la DICT · informe son personnel</text><rect class=\"bx\" x=\"8\" y=\"168\" width=\"344\" height=\"70\" rx=\"10\"/><circle class=\"dot\" cx=\"36\" cy=\"203\" r=\"18\"/><text class=\"dn\" x=\"36\" y=\"209\" text-anchor=\"middle\">EL</text><text class=\"t\" x=\"66\" y=\"194\">Exploitant</text><text class=\"s\" x=\"66\" y=\"216\">gère le réseau · répond par un récépissé</text><rect class=\"bx\" x=\"8\" y=\"248\" width=\"344\" height=\"70\" rx=\"10\"/><circle class=\"dot\" cx=\"36\" cy=\"283\" r=\"18\"/><text class=\"dn\" x=\"36\" y=\"289\" text-anchor=\"middle\">GU</text><text class=\"t\" x=\"66\" y=\"274\">Guichet unique</text><text class=\"s\" x=\"66\" y=\"296\">annuaire officiel des réseaux</text></svg>"}, {"id": "V02", "title": "Du guichet unique au chantier", "file": "V02.svg", "modules": [5, 7], "alt": "Les six étapes : guichet unique, DT, récépissé de DT, DICT, récépissé de DICT, chantier.", "ref": "S1 §5.1, §5.3 ; S8 R554-22, R554-26", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 552\" role=\"img\" aria-label=\"Du guichet unique au chantier\"><rect class=\"bx\" x=\"8\" y=\"8\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"41.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"46.0\" text-anchor=\"middle\">1</text><text class=\"t\" x=\"60\" y=\"35\">Guichet unique</text><text class=\"s\" x=\"60\" y=\"55\">qui a des réseaux près du chantier ?</text><text class=\"chip2\" x=\"344\" y=\"28\" text-anchor=\"end\">RP</text><path class=\"ar\" d=\"M180 76 v18 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"102\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"135.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"140.0\" text-anchor=\"middle\">2</text><text class=\"t\" x=\"60\" y=\"129\">DT</text><text class=\"s\" x=\"60\" y=\"149\">envoyée à chaque exploitant</text><text class=\"chip2\" x=\"344\" y=\"122\" text-anchor=\"end\">RP</text><path class=\"ar\" d=\"M180 170 v18 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"196\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"229.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"234.0\" text-anchor=\"middle\">3</text><text class=\"t\" x=\"60\" y=\"223\">Récépissé de DT</text><text class=\"s\" x=\"60\" y=\"243\">9 j · 15 j sur papier</text><text class=\"chip2\" x=\"344\" y=\"216\" text-anchor=\"end\">Exploitant</text><path class=\"ar\" d=\"M180 264 v18 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"290\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"323.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"328.0\" text-anchor=\"middle\">4</text><text class=\"t\" x=\"60\" y=\"317\">DICT</text><text class=\"s\" x=\"60\" y=\"337\">avant de commencer</text><text class=\"chip2\" x=\"344\" y=\"310\" text-anchor=\"end\">Exécutant</text><path class=\"ar\" d=\"M180 358 v18 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"384\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"417.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"422.0\" text-anchor=\"middle\">5</text><text class=\"t\" x=\"60\" y=\"411\">Récépissé de DICT</text><text class=\"s\" x=\"60\" y=\"431\">7 j · 9 j sur papier</text><text class=\"chip2\" x=\"344\" y=\"404\" text-anchor=\"end\">Exploitant</text><path class=\"ar\" d=\"M180 452 v18 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"478\" width=\"344\" height=\"66\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"511.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"516.0\" text-anchor=\"middle\">6</text><text class=\"t\" x=\"60\" y=\"505\">Chantier</text><text class=\"s\" x=\"60\" y=\"525\">récépissés et marquage sur place</text><text class=\"chip2\" x=\"344\" y=\"498\" text-anchor=\"end\">Exécutant</text></svg>"}, {"id": "V03", "title": "Classes de précision A, B, C", "file": "V03.svg", "modules": [6], "alt": "Trois barres proportionnelles aux incertitudes maximales des classes A, B et C.", "ref": "S6 art. 1", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 330\" role=\"img\" aria-label=\"Classes de précision A, B et C\"><text class=\"t\" x=\"10\" y=\"26\">Classe A</text><rect class=\"bar\" x=\"10\" y=\"36\" width=\"34\" height=\"22\" rx=\"4\"/><text class=\"s\" x=\"10\" y=\"80\">≤ 40 cm (rigide) · 50 cm (flexible)</text><text class=\"s\" x=\"10\" y=\"98\">Position fiable</text><text class=\"t\" x=\"10\" y=\"116\">Classe B</text><rect class=\"bar\" x=\"10\" y=\"126\" width=\"160\" height=\"22\" rx=\"4\"/><text class=\"s\" x=\"10\" y=\"170\">au-delà de A, jusqu'à 1,5 m (1 m branchements)</text><text class=\"s\" x=\"10\" y=\"188\">Approximatif</text><text class=\"t\" x=\"10\" y=\"206\">Classe C</text><rect class=\"bar\" x=\"10\" y=\"216\" width=\"340\" height=\"22\" rx=\"4\"/><text class=\"s\" x=\"10\" y=\"260\">plus de 1,5 m, ou position non fournie</text><text class=\"s\" x=\"10\" y=\"278\">Peu fiable : on ne creuse pas en confiance</text></svg>"}, {"id": "V04", "title": "Fuseau de précaution de 3 m", "file": "V04.svg", "modules": [6], "alt": "Vue de dessus : tracé théorique d'un réseau et fuseau de 3 m centrés, avec le tracé réel possible.", "ref": "S2 p. 8-9", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 300\" role=\"img\" aria-label=\"Fuseau de précaution de 3 m\"><rect class=\"band\" x=\"8\" y=\"80\" width=\"344\" height=\"120\" rx=\"4\"/><line class=\"dash\" x1=\"8\" y1=\"140\" x2=\"352\" y2=\"140\"/><path class=\"real\" d=\"M8 168 C90 150,150 190,220 160 S320 130,352 150\"/><text class=\"t\" x=\"180\" y=\"40\" text-anchor=\"middle\">Fuseau de 3 m</text><text class=\"s\" x=\"180\" y=\"62\" text-anchor=\"middle\">centré sur le tracé théorique</text><text class=\"s\" x=\"14\" y=\"132\">tracé théorique</text><text class=\"s\" x=\"14\" y=\"190\" >tracé réel possible</text><path class=\"ar\" d=\"M340 82 v114 m-6 -8 l6 8 l6 -8 m-12 -106 l6 -8 l6 8\"/><text class=\"s\" x=\"330\" y=\"146\" text-anchor=\"end\">3 m</text><text class=\"s\" x=\"180\" y=\"240\" text-anchor=\"middle\">2 m pour les branchements</text><text class=\"s\" x=\"180\" y=\"266\" text-anchor=\"middle\">Source : fascicule 2 v3, p. 8-9</text></svg>"}, {"id": "V05", "title": "La règle des 4 A", "file": "V05.svg", "modules": [8], "alt": "Arrêter, Alerter, Aménager, Accueillir.", "ref": "S1 §3.4 n ; S3 p. 42", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 330\" role=\"img\" aria-label=\"La règle des 4 A\"><rect class=\"bx\" x=\"6\" y=\"6\" width=\"168\" height=\"152\" rx=\"10\"/><text class=\"big\" x=\"90\" y=\"70\" text-anchor=\"middle\">A</text><text class=\"t\" x=\"90\" y=\"104\" text-anchor=\"middle\">Arrêter</text><text class=\"s\" x=\"90\" y=\"128\" text-anchor=\"middle\">les engins</text><rect class=\"bx\" x=\"186\" y=\"6\" width=\"168\" height=\"152\" rx=\"10\"/><text class=\"big\" x=\"270\" y=\"70\" text-anchor=\"middle\">A</text><text class=\"t\" x=\"270\" y=\"104\" text-anchor=\"middle\">Alerter</text><text class=\"s\" x=\"270\" y=\"128\" text-anchor=\"middle\">pompiers, puis exploitant</text><rect class=\"bx\" x=\"6\" y=\"170\" width=\"168\" height=\"152\" rx=\"10\"/><text class=\"big\" x=\"90\" y=\"234\" text-anchor=\"middle\">A</text><text class=\"t\" x=\"90\" y=\"268\" text-anchor=\"middle\">Aménager</text><text class=\"s\" x=\"90\" y=\"292\" text-anchor=\"middle\">une zone de sécurité</text><rect class=\"bx\" x=\"186\" y=\"170\" width=\"168\" height=\"152\" rx=\"10\"/><text class=\"big\" x=\"270\" y=\"234\" text-anchor=\"middle\">A</text><text class=\"t\" x=\"270\" y=\"268\" text-anchor=\"middle\">Accueillir</text><text class=\"s\" x=\"270\" y=\"292\" text-anchor=\"middle\">les secours</text></svg>"}, {"id": "V06", "title": "Avertisseurs en coupe", "file": "V06.svg", "modules": [2, 4], "alt": "Coupe du sol : grillage rouge au-dessus d'un câble, grillage jaune au-dessus d'une conduite de gaz, grillage violet au-dessus d'un réseau de chaleur.", "ref": "S2 §3.1.2, §3.4.2, §3.6.4", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 300\" role=\"img\" aria-label=\"Grillages avertisseurs en coupe\"><rect class=\"soil\" x=\"8\" y=\"60\" width=\"344\" height=\"226\"/><line class=\"gl\" x1=\"8\" y1=\"60\" x2=\"352\" y2=\"60\"/><line x1=\"8\" y1=\"118\" x2=\"116\" y2=\"118\" stroke=\"#c0392b\" stroke-width=\"5\"/><circle cx=\"62\" cy=\"168\" r=\"11\" fill=\"#555\"/><text class=\"s\" x=\"62\" y=\"205\" text-anchor=\"middle\">Électricité</text><text class=\"s\" x=\"62\" y=\"223\" text-anchor=\"middle\">grillage rouge</text><line x1=\"128\" y1=\"118\" x2=\"236\" y2=\"118\" stroke=\"#f2c200\" stroke-width=\"5\"/><circle cx=\"182\" cy=\"168\" r=\"14\" fill=\"#222\" stroke=\"#f2c200\" stroke-width=\"3\"/><text class=\"s\" x=\"182\" y=\"205\" text-anchor=\"middle\">Gaz</text><text class=\"s\" x=\"182\" y=\"223\" text-anchor=\"middle\">grillage jaune</text><line x1=\"248\" y1=\"118\" x2=\"352\" y2=\"118\" stroke=\"#7b3fa0\" stroke-width=\"5\"/><circle cx=\"300\" cy=\"168\" r=\"17\" fill=\"#888\"/><text class=\"s\" x=\"300\" y=\"205\" text-anchor=\"middle\">Chaleur, froid</text><text class=\"s\" x=\"300\" y=\"223\" text-anchor=\"middle\">grillage violet</text><text class=\"t\" x=\"180\" y=\"34\" text-anchor=\"middle\">Grillages avertisseurs, en coupe</text><text class=\"s\" x=\"180\" y=\"260\" text-anchor=\"middle\">Environ 20 cm au-dessus (électricité, gaz) · non systématiques</text><text class=\"s\" x=\"180\" y=\"280\" text-anchor=\"middle\">Source : fascicule 2 v3, §3.1.2, §3.4.2, §3.6.4</text></svg>"}, {"id": "V07", "title": "Distances aux lignes aériennes", "file": "V07.svg", "modules": [3], "alt": "Une ligne, une zone de 3 m sous 50 000 V, une zone de 5 m à partir de 50 000 V, un engin.", "ref": "S5 §3.1 ; S3 p. 30", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 330\" role=\"img\" aria-label=\"Distances aux lignes aériennes\"><rect class=\"soil\" x=\"8\" y=\"290\" width=\"344\" height=\"30\"/><rect x=\"60\" y=\"60\" width=\"8\" height=\"230\" fill=\"#7a6a58\"/><line x1=\"10\" y1=\"64\" x2=\"350\" y2=\"64\" stroke=\"#222\" stroke-width=\"3\"/><circle class=\"zone5\" cx=\"64\" cy=\"64\" r=\"150\"/><circle class=\"zone3\" cx=\"64\" cy=\"64\" r=\"90\"/><rect x=\"260\" y=\"238\" width=\"70\" height=\"46\" rx=\"6\" class=\"eng\"/><rect x=\"214\" y=\"150\" width=\"62\" height=\"10\" transform=\"rotate(-48 260 238)\" class=\"eng\"/><text class=\"t\" x=\"180\" y=\"30\" text-anchor=\"middle\">Ligne aérienne et distances</text><text class=\"s\" x=\"64\" y=\"52\" text-anchor=\"middle\">ligne</text><text class=\"s\" x=\"170\" y=\"104\">3 m : sous 50 000 V</text><text class=\"s\" x=\"190\" y=\"204\">5 m : à partir de 50 000 V</text><text class=\"s\" x=\"180\" y=\"326\" text-anchor=\"middle\">Engin et charge compris · schéma non à l'échelle</text></svg>"}, {"id": "V08", "title": "Le marquage dans la vie du chantier", "file": "V08.svg", "modules": [4], "alt": "Frise : fait par le responsable de projet, compte rendu remis à l'exécutant, entretenu, dégradable en 6 mois.", "ref": "S1 §3.2 i, §3.4 f, m ; S3 p. 37 ; S6 art. 7 IV", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 336\" role=\"img\" aria-label=\"Le marquage-piquetage\"><rect class=\"bx\" x=\"8\" y=\"8\" width=\"344\" height=\"62\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"39.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"44.0\" text-anchor=\"middle\">1</text><text class=\"t\" x=\"60\" y=\"35\">Fait faire par le responsable de projet</text><text class=\"s\" x=\"60\" y=\"55\">avant le démarrage, dans l'emprise et à moins de 2 m</text><path class=\"ar\" d=\"M180 72 v14 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"94\" width=\"344\" height=\"62\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"125.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"130.0\" text-anchor=\"middle\">2</text><text class=\"t\" x=\"60\" y=\"121\">Compte rendu signé</text><text class=\"s\" x=\"60\" y=\"141\">remis à l'exécutant, gardé sur le chantier</text><path class=\"ar\" d=\"M180 158 v14 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"180\" width=\"344\" height=\"62\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"211.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"216.0\" text-anchor=\"middle\">3</text><text class=\"t\" x=\"60\" y=\"207\">Entretenu par l'exécutant</text><text class=\"s\" x=\"60\" y=\"227\">maintenu en bon état pendant toute la durée</text><path class=\"ar\" d=\"M180 244 v14 m-6 -7 l6 7 l6 -7\"/><rect class=\"bx\" x=\"8\" y=\"266\" width=\"344\" height=\"62\" rx=\"10\"/><circle class=\"dot\" cx=\"34\" cy=\"297.0\" r=\"14\"/><text class=\"dn\" x=\"34\" y=\"302.0\" text-anchor=\"middle\">4</text><text class=\"t\" x=\"60\" y=\"293\">Dégradable en 6 mois au plus</text><text class=\"s\" x=\"60\" y=\"313\">à refaire si le chantier dure</text></svg>"}, {"id": "V09", "title": "Concepteur, encadrant, opérateur", "file": "V09.svg", "modules": [1], "alt": "Trois cercles emboîtés : l'attestation de concepteur couvre encadrant et opérateur.", "ref": "S3 p. 14 ; S7", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 330\" role=\"img\" aria-label=\"Concepteur, encadrant, opérateur\"><circle class=\"c1\" cx=\"180\" cy=\"170\" r=\"150\"/><circle class=\"c2\" cx=\"180\" cy=\"210\" r=\"104\"/><circle class=\"c3\" cx=\"180\" cy=\"250\" r=\"56\"/><text class=\"t\" x=\"180\" y=\"48\" text-anchor=\"middle\">Concepteur · 40 questions</text><text class=\"s\" x=\"180\" y=\"68\" text-anchor=\"middle\">couvre aussi encadrant et opérateur</text><text class=\"t\" x=\"180\" y=\"136\" text-anchor=\"middle\">Encadrant · 40 questions</text><text class=\"s\" x=\"180\" y=\"156\" text-anchor=\"middle\">couvre aussi opérateur</text><text class=\"t\" x=\"180\" y=\"248\" text-anchor=\"middle\">Opérateur</text><text class=\"s\" x=\"180\" y=\"268\" text-anchor=\"middle\">30 questions</text></svg>"}, {"id": "V11", "title": "Couleurs du marquage-piquetage", "file": "V11.svg", "modules": [4], "alt": "Neuf couleurs de marquage : rouge électricité, jaune gaz et hydrocarbures, orange produits chimiques, bleu eau potable, marron assainissement, violet chaleur et froid, vert télécoms, blanc équipements routiers, rose réseaux proches.", "ref": "S4 p. 32 (annexe 4, édition 2014)", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 340\" role=\"img\" aria-label=\"Couleurs du marquage-piquetage\"><rect x=\"8\" y=\"8\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"12\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#c0392b\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"28\">Rouge</text><text class=\"s\" x=\"140\" y=\"28\">Électricité, éclairage public</text><rect x=\"8\" y=\"42\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"46\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#f2c200\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"62\">Jaune</text><text class=\"s\" x=\"140\" y=\"62\">Gaz, hydrocarbures</text><rect x=\"8\" y=\"76\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"80\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#e67e22\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"96\">Orange</text><text class=\"s\" x=\"140\" y=\"96\">Gaz industriels, produits chimiques</text><rect x=\"8\" y=\"110\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"114\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#1f6fd1\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"130\">Bleu</text><text class=\"s\" x=\"140\" y=\"130\">Eau potable</text><rect x=\"8\" y=\"144\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"148\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#7b4a21\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"164\">Marron</text><text class=\"s\" x=\"140\" y=\"164\">Assainissement</text><rect x=\"8\" y=\"178\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"182\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#7b3fa0\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"198\">Violet</text><text class=\"s\" x=\"140\" y=\"198\">Chauffage, climatisation urbains</text><rect x=\"8\" y=\"212\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"216\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#2e9d4f\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"232\">Vert</text><text class=\"s\" x=\"140\" y=\"232\">Télécommunications</text><rect x=\"8\" y=\"246\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"250\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#ffffff\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"266\">Blanc</text><text class=\"s\" x=\"140\" y=\"266\">Équipements routiers (TBT)</text><rect x=\"8\" y=\"280\" width=\"344\" height=\"30\" rx=\"6\" class=\"bx\"/><rect x=\"14\" y=\"284\" width=\"46\" height=\"22\" rx=\"4\" fill=\"#f06fa8\" stroke=\"#555\" stroke-width=\"1\"/><text class=\"t\" x=\"70\" y=\"300\">Rose</text><text class=\"s\" x=\"140\" y=\"300\">Réseaux différents très proches</text><text class=\"s\" x=\"180\" y=\"330\" text-anchor=\"middle\">Source : INRS ED 6164 (2014), annexe 4, p. 32</text></svg>"}, {"id": "V10", "title": "Barème de l'examen", "file": "V10.svg", "modules": [], "alt": "+2, 0, −1, −5.", "ref": "S7 art. 2", "svg": "<svg class=\"sv\" viewBox=\"0 0 360 260\" role=\"img\" aria-label=\"Barème de l'examen\"><rect class=\"bx\" x=\"8\" y=\"8\" width=\"344\" height=\"52\" rx=\"10\"/><text class=\"t\" x=\"24\" y=\"40\">Bonne réponse</text><text class=\"big2\" x=\"336\" y=\"42\" text-anchor=\"end\">+2</text><rect class=\"bx\" x=\"8\" y=\"68\" width=\"344\" height=\"52\" rx=\"10\"/><text class=\"t\" x=\"24\" y=\"100\">Je ne sais pas</text><text class=\"big2\" x=\"336\" y=\"102\" text-anchor=\"end\">0</text><rect class=\"bx\" x=\"8\" y=\"128\" width=\"344\" height=\"52\" rx=\"10\"/><text class=\"t\" x=\"24\" y=\"160\">Mauvaise réponse</text><text class=\"big2\" x=\"336\" y=\"162\" text-anchor=\"end\">−1</text><rect class=\"bx\" x=\"8\" y=\"188\" width=\"344\" height=\"52\" rx=\"10\"/><text class=\"t\" x=\"24\" y=\"220\">Mauvaise réponse prioritaire</text><text class=\"big2\" x=\"336\" y=\"222\" text-anchor=\"end\">−5</text></svg>"}], "illus": [{"id": "I01", "file": "ill-01.webp", "title": "Réseau inconnu dans la fouille", "alt": "Deux ouvriers s'écartent d'une tranchée où apparaît un câble ; une pelle est à l'arrêt.", "modules": [7]}, {"id": "I02", "file": "ill-02.webp", "title": "Godet au contact d'une canalisation", "alt": "Gros plan d'un godet de pelle au contact d'une canalisation enterrée.", "modules": [8]}, {"id": "I03", "file": "ill-03.webp", "title": "Zone sécurisée après incident", "alt": "Engin arrêté derrière un balisage, un ouvrier téléphone, un autre guide l'arrivée des véhicules de secours.", "modules": [8]}, {"id": "I04", "file": "ill-04.webp", "title": "Marquage au sol partiellement effacé", "alt": "Chaussée avec traces de marquage en partie effacées.", "modules": [4]}, {"id": "I05", "file": "ill-05.webp", "title": "Lire ensemble un plan de réseaux", "alt": "Deux professionnels consultent un plan de réseaux sur tablette devant une zone de travaux.", "modules": [5, 6]}, {"id": "I06", "file": "ill-06.webp", "title": "Grue de camion près d'une ligne aérienne", "alt": "Camion-grue déposant un élément en béton dans une tranchée, avec une ligne électrique aérienne à proximité.", "modules": [3]}], "glossary": [["AIPR", "Autorisation d'intervention à proximité des réseaux. Délivrée par l'employeur."], ["DT", "Déclaration de projet de travaux, établie par le responsable de projet."], ["DICT", "Déclaration d'intention de commencement de travaux, établie par l'exécutant."], ["Récépissé", "Réponse de l'exploitant à une déclaration."], ["Exploitant", "Celui qui gère un réseau."], ["Responsable de projet", "Celui qui décide des travaux (maître d'ouvrage), y compris un particulier."], ["Exécutant des travaux", "Celui qui réalise les travaux."], ["Guichet unique", "Annuaire officiel des réseaux (téléservice de l'INERIS)."], ["Réseau sensible", "Réseau dont l'endommagement peut menacer la sécurité (gaz, lignes électriques…)."], ["Classe A, B, C", "Niveaux de précision du plan : A très précis, C peu fiable."], ["Investigations complémentaires (IC)", "Sondages pour localiser précisément un réseau, par un prestataire certifié."], ["Marquage-piquetage", "Repérage au sol de l'emplacement des réseaux."], ["ATU", "Avis de travaux urgents."], ["Constat contradictoire", "Constat établi avec l'exploitant après un endommagement (Cerfa 14766*02)."], ["Règle des 4 A", "Arrêter, Alerter, Aménager, Accueillir."], ["Opérateur", "Conducteur d'engins qui intervient pour l'exécutant."], ["Encadrant", "Profil AIPR de celui qui encadre le chantier pour l'exécutant."], ["Concepteur", "Profil AIPR de celui qui intervient pour le responsable de projet."], ["Attestation de compétences", "Document remis après réussite au QCM ; l'employeur délivre ensuite l'AIPR."], ["Question prioritaire", "Question d'examen dont une mauvaise réponse retire 5 points."], ["Emprise", "Zone occupée par le chantier."], ["Fuseau", "Bande autour du tracé supposé d'un réseau où la position réelle est incertaine."], ["Affleurant", "Élément visible en surface d'un réseau enterré (regard, coffret, borne…)."], ["Rigide / flexible", "Deux types d'ouvrage ; la précision exigée en classe A diffère (40 cm / 50 cm)."], ["PE / PEHD", "Polyéthylène / polyéthylène haute densité."], ["PCRS", "Plan corps de rue simplifié."], ["Unité urbaine", "Zone urbanisée ; elle conditionne des échéances de classe A."]], "resources": [["Guichet unique des réseaux et canalisations", "https://www.reseaux-et-canalisations.ineris.fr/", "Portail officiel : consultation, formulaires, guide d'application.", "Portail non parcouru en entier"], ["Fascicule 1 — guide d'application", "https://www.reseaux-et-canalisations.ineris.fr/gu-presentation/userfile?path=/fichiers/Guides_techniques/Fascicule1_en_vigueur_01012020.pdf", "Rôles et procédures.", "Lu partiellement le 26/10/2026"], ["Fascicule 2 — guide technique v3", "https://www.observatoire-national-dt-dict.fr/wp-content/uploads/2024/05/2024_Fascicule-2-GUIDE-TECHNIQUE_V3.pdf", "Caractéristiques des réseaux et techniques.", "Lu jusqu'à la p. 43"], ["Guide pratique FFB, FNTP, OPPBTP, SGAMbtp", "https://www.smabtp.fr/sma/upload/docs/application/pdf/2023-01/guide_travaux_a_proximite_des_reseaux__200123.pdf", "Mise en œuvre, checklists, AIPR.", "Lu jusqu'à la p. 46"], ["INRS ED 6292 — réseaux électriques aériens", "https://www.inrs.fr/dam/inrs/CataloguePapier/ED/TI-ED-6292.pdf", "Distances et détecteurs.", "Lu pour les distances"], ["INRS ED 6164 — travaux à proximité des réseaux", "https://www.inrs.fr/dam/inrs/CataloguePapier/ED/TI-ED-6164.pdf", "Aide-mémoire technique (édition 2014).", "Lu partiellement"], ["Arrêté du 22/12/2015 — contrôle des compétences", "https://aida.ineris.fr/reglementation/arrete-221215-relatif-controle-competences-personnes-intervenant-travaux-a-proximite", "Examen AIPR.", "Lu (art. 2)"], ["Arrêté du 15/02/2012 modifié", "https://aida.ineris.fr/reglementation/arrete-150212-pris-application-chapitre-iv-titre-v-livre-v-code-lenvironnement", "Classes de précision, marquage.", "Lu jusqu'à l'art. 13"], ["QCM-AIPR (plateforme officielle d'examen)", "https://qcm-aipr.din.developpement-durable.gouv.fr/", "Plateforme de passage de l'examen.", "Page d'accueil seulement"]], "rex": [{"date": "11/01/2024", "lieu": "Les Sables-d'Olonne (85)", "res": "Gaz naturel", "faits": "Lors de travaux d'un tiers, un engin heurte une canalisation de gaz enterrée. Le chantier est évacué avant l'arrivée des secours. Les pompiers évacuent les habitations voisines et bouclent un périmètre. Le gestionnaire coupe le gaz à 750 clients. Aucun blessé mentionné.", "lecon": "Le chantier a été évacué sans attendre : c'est le réflexe « arrêter, alerter ». La fiche ne dit rien du repérage préalable.", "module": 8, "src": "S12 (ARIA 61637)"}, {"date": "16/01/2024", "lieu": "Argentan (61)", "res": "Gaz naturel, 2,5 bar", "faits": "Un engin de chantier endommage une canalisation de gaz enterrée. Les services du gaz ferment les vannes au niveau de la fouille. Neuf personnes sont évacuées, la rue est coupée, 520 abonnés sont privés de gaz. Aucun blessé mentionné.", "lecon": "Un seul coup de godet suffit à couper le gaz à plus de 500 foyers. La fiche ne précise pas les causes profondes.", "module": 8, "src": "S12 (ARIA 61751)"}, {"date": "10/03/2017", "lieu": "Saint-Herblain (44)", "res": "Gaz naturel", "faits": "Un engin de terrassement endommage une canalisation de gaz. L'enquête relève trois constats : l'exécutant travaillait en dehors de la zone déclarée dans la DICT ; le projet de réseau figurait dans les informations qu'il avait, mais n'a pas été pris en compte ; les DICT n'avaient pas été renouvelées. 648 clients sont privés de gaz.", "lecon": "Trois erreurs d'organisation, aucune de technique : zone de la DICT, informations non lues, DICT non renouvelée.", "module": 5, "src": "S12 (ARIA 49925) ; S11"}, {"date": "28/02/2008", "lieu": "Rhône", "res": "Gaz", "faits": "Fuite de gaz sur un chantier d'eau en centre-ville, puis explosion et incendie. Selon la synthèse BARPI : un pompier tué, une quarantaine de blessés, 500 à 1 000 personnes évacuées, locaux inhabités pendant plusieurs années. La synthèse relève des imprudences et un manquement à une obligation réglementaire.", "lecon": "Un chantier d'eau peut déclencher un accident de gaz. Fiche ARIA d'origine non consultée.", "module": 8, "src": "S11 (ARIA 34280)"}, {"date": "14/11/2011", "lieu": "Sotteville-lès-Rouen (76)", "res": "Gaz (presse)", "faits": "Selon la presse locale, un engin d'une entreprise de travaux publics a arraché une canalisation de gaz sur un chantier de voirie. Situation maîtrisée en 30 minutes, personne n'a été évacué.", "lecon": "Un exemple de presse, antérieur à la réforme de 2012 : à utiliser comme illustration, pas comme statistique.", "module": 8, "src": "S15"}, {"date": "Non datée", "lieu": "Non précisé", "res": "Électricité 400 V", "faits": "Dans un dossier de la revue de l'INRS, un accident de démoussage est cité : une nacelle est entrée en contact avec une ligne de 400 V, sans DICT ni mise hors tension.", "lecon": "Les accidents électriques sont rares mais graves : près de dix décès par an pour le régime général.", "module": 3, "src": "S13"}], "rexStats": [["Plus de 1 500 événements d'endommagement de réseaux à risque dans la base ARIA, avec une baisse depuis 2012. Pour le gaz, seuls les événements avec évacuation d'au moins 300 personnes ou arrêt d'au moins 500 clients sont recensés depuis 2011.", "S11"], ["Environ 100 000 dommages par an en 2007, environ 65 000 fin 2015 (hors eau et assainissement). Chiffres anciens, à ne pas présenter comme actuels.", "S14"], ["Près de dix décès par an de travailleurs du régime général après un accident sur ligne électrique. Le BTP est le secteur le plus touché.", "S13"]], "rexCauses": ["DICT non renouvelée ou zone de travail différente de celle déclarée (ARIA 49925)", "Plans erronés, profondeurs inversées, ouvrage non vérifié (ARIA 49062, cité par S11)", "Information reçue mais non prise en compte (ARIA 49925)", "Absence de DICT ou de mise hors tension sur une ligne électrique (S13)", "Réseaux « fantômes » absents des plans (S13)"], "extPhotos": [["Pipeline Trench Excavation", "Sabino Freitas Correa", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Pipeline_Trench_Excavation.jpg"], ["Excavator 0025", "Rami Tarawneh", "CC BY 2.5", "https://commons.wikimedia.org/wiki/File:Excavator_0025.jpg"], ["Excavation of pipe", "Robertosplumbing", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Excavation_of_pipe.jpg"]]};window.TRAINER_PACK={"salt": "0APoQKvNr4n62g6LIGYVxw==", "it": 250000, "iv": "PnajD9mkTDRBOJJZ", "ct": ""};